static const char runtime_source[] =
"/* phx.h -- the shapes Phoenix works in.\n"
" *\n"
" * Stage 0 is the grammar half and nothing else: read a `.phx` file that holds\n"
" * only EBNF, scan a target file into tokens with it, match those tokens\n"
" * against it, and print the tree that came out. No actions, no passes, no\n"
" * code generation -- those arrive in later stages, and this file grows with\n"
" * them rather than anticipating them.\n"
" */\n"
"#ifndef PHX_H\n"
"#define PHX_H\n"
"\n"
"#include <stdbool.h>\n"
"#include <stddef.h>\n"
"#include <stdio.h>\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Arena\n"
" *\n"
" * Nothing is freed until the process is done with it. A compiler-compiler\n"
" * reads a grammar, walks a file and exits; lifetimes are one run long, and an\n"
" * allocator that says so is smaller than one that tracks them.\n"
" */\n"
"\n"
"typedef struct Arena Arena;\n"
"\n"
"Arena *arena_new(void);\n"
"void   arena_free(Arena *a);\n"
"void  *arena_alloc(Arena *a, size_t n);\n"
"char  *arena_strndup(Arena *a, const char *s, size_t n);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Source\n"
" *\n"
" * A file, held whole. Positions are byte offsets and nothing carries a line:\n"
" * the line is wanted a few times per run, once per message, and counting\n"
" * newlines on demand is free at that rate. Carrying one on every token and\n"
" * every node is a field on everything.\n"
" */\n"
"\n"
"/* A description may be assembled from several files, and a position has to\n"
" * name the one it came from. The text of every file is held end to end in one\n"
" * buffer so that an offset stays a single number, and a map says which file\n"
" * each stretch of it came from. Everything downstream keeps working with plain\n"
" * offsets and gets the right filename and line without knowing any of this. */\n"
"\n"
"typedef struct {\n"
"    const char *path;\n"
"    size_t      start;    /* where this file begins in the joined text */\n"
"    size_t      size;\n"
"} Unit;\n"
"\n"
"typedef struct {\n"
"    Unit *units;\n"
"    int   n;\n"
"    int   cap;\n"
"} SourceMap;\n"
"\n"
"typedef struct {\n"
"    const char      *path;\n"
"    char            *text;\n"
"    size_t           size;\n"
"    const SourceMap *map;    /* NULL when the text is one file */\n"
"} Source;\n"
"\n"
"bool source_read(Arena *a, const char *path, Source *out);\n"
"\n"
"/* The same, saying nothing when the file is not there -- for looking in more\n"
" * than one place before deciding a file is missing. */\n"
"bool source_try(Arena *a, const char *path, Source *out);\n"
"void source_position(const Source *src, size_t off, int *line, int *col);\n"
"void source_line(const Source *src, size_t off, const char **start, size_t *len);\n"
"\n"
"/* Which file an offset falls in. The source's own path when there is no map. */\n"
"const char *source_path_at(const Source *src, size_t off);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Diagnostics\n"
" *\n"
" * Every message names a file, a line and a column, and prints the line with a\n"
" * caret under it. `diag_error` records that something failed; the exit status\n"
" * is a question to `diag_failed`.\n"
" */\n"
"\n"
"void diag_error(const Source *src, size_t off, const char *fmt, ...);\n"
"void diag_warn(const Source *src, size_t off, const char *fmt, ...);\n"
"void diag_note(const char *fmt, ...);\n"
"bool diag_failed(void);\n"
"int  diag_errors(void);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* What a production builds\n"
" *\n"
" * `-> ` after an alternative says what that alternative *means*, as opposed to\n"
" * what it looks like. Without one, a rule answers what it matched and the tree\n"
" * is the concrete one -- every bracket and semicolon in it. With one, the rule\n"
" * answers the node named there.\n"
" *\n"
" *     statement = \"print\" expression \";\"   -> Print(expr: $2)\n"
" *               | \"let\" name \":=\" expression \";\" -> Let(name: $2, value: $4) .\n"
" *\n"
" * `$n` is the n'th factor of the sequence, counting from one and counting\n"
" * everything -- so `$2` above is the `expression` and `$3` the `\";\"`. A factor\n"
" * may be given a name instead, which survives the sequence being edited:\n"
" *\n"
" *     statement = \"print\" e:expression \";\"  -> Print(expr: $e) .\n"
" *\n"
" * `$$` is what has been built so far, and is what makes a left fold sayable.\n"
" * An action mentioning it *replaces* the value before it rather than following\n"
" * it, so the flat repetition every grammar writes for a binary operator comes\n"
" * out as the left-leaning tree it means:\n"
" *\n"
" *     expression = term { ( \"+\" | \"-\" ) term -> Binary(op: $1, left: $$, right: $2) } .\n"
" */\n"
"\n"
"typedef enum {\n"
"    X_NODE,    /* Type(field: value, ...), or a bare Type with no fields    */\n"
"    X_REF,     /* $2, or $name                                              */\n"
"    X_ACC,     /* $$ -- what the enclosing sequence has built so far        */\n"
"    X_TEXT,    /* \"a literal\"                                               */\n"
"    X_LIST,    /* [ a, b ]                                                  */\n"
"    X_SPREAD,  /* ...a  -- inside a list, opens a list out into it          */\n"
"    X_INT,     /* 45                                                        */\n"
"    X_FLOAT,   /* 4.5                                                       */\n"
"    X_BOOL,    /* true, false                                               */\n"
"    X_NIL,     /* nil                                                       */\n"
"    X_BINOP,   /* a + b   -- the spelling in `name`                         */\n"
"    X_UNOP,    /* not a, -a                                                 */\n"
"    X_CALL,    /* f(a, b)                                                   */\n"
"    X_DOT,     /* $left.val -- an attribute of another node                 */\n"
"    X_FORMAT   /* \"{} {}\" of a, b                                           */\n"
"} XKind;\n"
"\n"
"typedef struct Expr Expr;\n"
"struct Expr {\n"
"    XKind      kind;\n"
"    char      *name;   /* X_NODE: the type. X_REF/X_DOT: the name.\n"
"                        * X_TEXT: the bytes. X_BINOP/X_UNOP/X_CALL: which    */\n"
"    int        len;    /* X_TEXT: its length                                 */\n"
"    int        index;  /* X_REF: the 1-based position, or 0 when by name     */\n"
"    long long  ival;   /* X_INT, X_BOOL                                      */\n"
"    double     real;   /* X_FLOAT                                            */\n"
"    char     **fields; /* X_NODE: one name per kid, else NULL throughout     */\n"
"    Expr     **kids;\n"
"    int        nkids;\n"
"    size_t     pos;\n"
"};\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* The tree a grammar is\n"
" *\n"
" * Wirth's notation, plus the three things it needs before it can describe a\n"
" * lexer and not one thing more: a character range, a negation, and the string\n"
" * escapes. All three are lexical only, and using one in a syntactic rule --\n"
" * where there are tokens and no characters to ask about -- is an error with a\n"
" * line number.\n"
" */\n"
"\n"
"typedef enum {\n"
"    G_LIT,    /* \"text\"        a terminal: characters, or a token's spelling */\n"
"    G_RANGE,  /* \"a\" .. \"z\"    one character between two, inclusive          */\n"
"    G_NAME,   /* rule-name     a reference, resolved to an index             */\n"
"    G_SEQ,    /* a b c         all of them, in order                         */\n"
"    G_ALT,    /* a | b         ordered choice: b is tried only if a failed   */\n"
"    G_OPT,    /* [ a ]         a, or nothing                                 */\n"
"    G_REP,    /* { a }         a as many times as it will go, greedily       */\n"
"    G_NOT     /* ! a           one character, provided a does not match here */\n"
"} GKind;\n"
"\n"
"typedef struct GNode GNode;\n"
"struct GNode {\n"
"    GKind   kind;\n"
"    char   *text;    /* LIT: the text.  RANGE: the low end.  NAME: the name  */\n"
"    char   *upto;    /* RANGE: the high end                                  */\n"
"    char   *folded;  /* LIT: text lowercased, for %ignorecase                */\n"
"    int     len;     /* LIT: its length, since a literal may hold a NUL      */\n"
"    GNode **kids;\n"
"    int     nkids;\n"
"    int     ref;     /* NAME: the rule it names, or -1 until resolved        */\n"
"    char   *label;   /* the name a factor was given: `e:expression`          */\n"
"    Expr   *action;  /* SEQ: what this alternative builds, or NULL           */\n"
"    size_t  pos;\n"
"};\n"
"\n"
"typedef struct {\n"
"    char   *name;\n"
"    GNode  *body;\n"
"    bool    lexical;   /* declared before %syntax                           */\n"
"    bool    fragment;  /* %fragment: a helper, never a token on its own     */\n"
"    bool    skip;      /* %skip: produced, then thrown away                 */\n"
"    bool    used;      /* referred to by some other rule                    */\n"
"    bool    required;  /* %require: a hole, filled by whoever imports this   */\n"
"    bool    nullable;  /* can match nothing -- wanted by the checks         */\n"
"    size_t  pos;\n"
"} Rule;\n"
"\n"
"typedef struct Pass    Pass;   /* below -- the Grammar holds them */\n"
"typedef struct Driver  Driver;\n"
"typedef struct Rewrite Rewrite;\n"
"\n"
"typedef struct {\n"
"    Arena     *arena;\n"
"    Source     src;         /* every imported file, joined */\n"
"    SourceMap  map;\n"
"\n"
"    char     **imported;    /* the paths already read, so none is read twice */\n"
"    int        nimported;\n"
"    int        capimported;\n"
"\n"
"    Rule   *rules;\n"
"    int     nrules;\n"
"    int     caprules;\n"
"\n"
"    int     start;       /* the goal rule                                   */\n"
"    bool    ignorecase;\n"
"\n"
"    char  **reserved;    /* word-shaped literals from the syntactic half    */\n"
"    int     nreserved;\n"
"\n"
"    Pass   *passes;\n"
"    int     npasses;\n"
"    int     cappasses;\n"
"\n"
"    Driver *drivers;\n"
"    int     ndrivers;\n"
"    int     capdrivers;\n"
"\n"
"    Rewrite *rewrites;\n"
"    int      nrewrites;\n"
"    int      caprewrites;\n"
"\n"
"    /* `%include Include path` -- which node stands for a target file's own\n"
"     * include, and which of its fields holds the name of the file. NULL when\n"
"     * the language has no such thing, which is most of them. */\n"
"    char   *include_type;\n"
"    char   *include_field;\n"
"    size_t  include_pos;     /* where it was declared, for the checks       */\n"
"\n"
"    /* A module may name rules it does not define. Reading one on its own is\n"
"     * fine; using one to parse a file is not, and this is what says so. */\n"
"    bool    incomplete;\n"
"} Grammar;\n"
"\n"
"/* Reads a `.phx` file. Answers NULL when it could not, having said why. */\n"
"Grammar *grammar_read(Arena *a, const char *path);\n"
"\n"
"/* Resolves names and runs every check. Reports as it goes. */\n"
"bool grammar_check(Grammar *g);\n"
"\n"
"/* Prints the grammar back in the notation it was written in. */\n"
"void grammar_dump(FILE *out, const Grammar *g);\n"
"\n"
"/* Prints the node types the grammar can build, and their fields -- the\n"
" * vocabulary a pass will be written against. */\n"
"void grammar_nodes(FILE *out, const Grammar *g);\n"
"\n"
"/* Finds a rule by name, or -1. */\n"
"int grammar_find(const Grammar *g, const char *name, size_t len);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Passes\n"
" *\n"
" * A pass is clauses keyed on the vocabulary the actions build. Clauses are\n"
" * tried **in order and the first match wins** -- the same dispatch discipline\n"
" * as the ordered choice in the syntactic half, so the tool has one rule about\n"
" * ordering rather than two.\n"
" *\n"
" *     %pass eval\n"
" *       thread env = empty\n"
" *\n"
" *       Number          : val = number($text) .\n"
" *       Binary(op: \"+\") : val = $left.val + $right.val .\n"
" *       Let             : env = bind($env, $name, $value.val) .\n"
" *       Variable        : val = lookup($env, $name) .\n"
" *                       ! error(\"'{}' is not defined\" of $name)\n"
" *                           when lookup($env, $name) = nil .\n"
" *\n"
" * A pattern tests and binds at once: `Number(text: t)` matches a `Number` and\n"
" * binds `t`. A field written with a value tests it; a field written with a\n"
" * name binds it; a field left out is not looked at.\n"
" *\n"
" * A **list** is written `[ a, b ]` and matches a list of exactly that many,\n"
" * each element matching. A value can be a list, so a pattern has to be able to\n"
" * be one -- without it there is no way to ask about a field that holds several\n"
" * things, and `Send(args: [Block(params: [])])`, which is exactly the\n"
" * question an optimisation asks, cannot be written at all.\n"
" */\n"
"\n"
"typedef enum {\n"
"    P_TYPE,   /* Binary, or Binary(op: \"+\")                                 */\n"
"    P_BIND,   /* a name: matches anything and binds it                      */\n"
"    P_TEXT,   /* \"literal\"                                                  */\n"
"    P_INT,    /* 45                                                         */\n"
"    P_BOOL,   /* true, false                                                */\n"
"    P_NIL,    /* nil                                                        */\n"
"    P_LIST,   /* [ a, b ] -- a list of exactly that many, each matching     */\n"
"    P_ANY     /* _                                                          */\n"
"} PKind;\n"
"\n"
"typedef struct Pattern Pattern;\n"
"struct Pattern {\n"
"    PKind      kind;\n"
"    char      *name;    /* P_TYPE: the type. P_BIND: the name. P_TEXT: bytes */\n"
"    int        len;\n"
"    long long  ival;\n"
"    char     **fields;  /* P_TYPE: which field each kid tests                */\n"
"    Pattern  **kids;\n"
"    int        nkids;\n"
"    size_t     pos;\n"
"};\n"
"\n"
"typedef enum {\n"
"    C_SYNTH,   /* attr = expr      -- computed from this node and its kids  */\n"
"    C_DOWN,    /* down attr = expr -- handed to the children                */\n"
"    C_THREAD,  /* a threaded attribute's update, recognised by its name     */\n"
"    C_ERROR    /* ! error(...) when cond                                    */\n"
"} CKind;\n"
"\n"
"typedef struct {\n"
"    CKind   kind;\n"
"    char   *attr;    /* the attribute defined, for the three that define one */\n"
"    Expr   *value;   /* the expression, or the message for C_ERROR           */\n"
"    Expr   *when;    /* C_ERROR: the condition, or NULL for always           */\n"
"    size_t  pos;\n"
"} Clause;\n"
"\n"
"typedef struct {\n"
"    Pattern *pattern;\n"
"    Clause  *clauses;\n"
"    int      nclauses;\n"
"    size_t   pos;\n"
"} PassRule;\n"
"\n"
"struct Pass {\n"
"    char     *name;\n"
"    char    **threads;    /* the threaded attributes, in order declared      */\n"
"    Expr    **initial;    /* what each one enters the root with              */\n"
"    int       nthreads;\n"
"    PassRule *rules;\n"
"    int       nrules;\n"
"\n"
"    /* `otherwise type = \"void\"` -- what a node has when its own rule does not\n"
"     * work one out.\n"
"     *\n"
"     * A clause is keyed on a node type, and some attributes are answered the\n"
"     * same way by nearly every type. `languages/pascal/pascal.phx` wrote\n"
"     * `type = \"void\"` twenty-one times so that a node above could read a type\n"
"     * without asking which kind of statement it was; the `.sob` backend would\n"
"     * have written one line of a run table once per node type that can be a\n"
"     * statement.\n"
"     *\n"
"     * **It is still a clause about a node**, which is the whole reason this is\n"
"     * the mechanism rather than a function or a macro: the general one. It\n"
"     * runs after the node's own clauses, so it can read what they worked out,\n"
"     * and only for the attributes that rule left alone.\n"
"     */\n"
"    Clause   *defaults;\n"
"    int       ndefaults;\n"
"\n"
"    size_t    pos;\n"
"};\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Rewrites\n"
" *\n"
" *     %rewrite fold bottomup\n"
" *       Binary(op: \"+\", left: Number(text: a), right: Number(text: b))\n"
" *         => Number(text: text(int(a) + int(b))) .\n"
" *\n"
" * A pass **decorates**: it works out attributes and leaves the tree alone. A\n"
" * rewrite **replaces**: a node whose shape matches becomes what the `=>` says,\n"
" * and the walk carries on. The two halves were already here -- patterns match\n"
" * on shape and bind, and the evaluator builds nodes -- so what this adds is a\n"
" * traversal that puts the answer back.\n"
" *\n"
" * It is what a pass cannot do, and the reason is the same one that made\n"
" * `%include` a reader's job rather than a clause's: a pass answers *about* a\n"
" * node, and some things are answered by there being a different node.\n"
" *\n"
" * The strategy says when a node is tried against its children:\n"
" *\n"
" *   bottomup   children first, then this node, once\n"
" *   topdown    this node first, then the children of whatever it became\n"
" *   innermost  bottom-up, and again on the result until nothing matches\n"
" */\n"
"\n"
"typedef enum {\n"
"    R_BOTTOMUP,\n"
"    R_TOPDOWN,\n"
"    R_INNERMOST\n"
"} RStrategy;\n"
"\n"
"typedef struct {\n"
"    Pattern *pattern;\n"
"    Expr    *to;\n"
"    size_t   pos;\n"
"} RewriteRule;\n"
"\n"
"struct Rewrite {\n"
"    char        *name;\n"
"    RStrategy    how;\n"
"    RewriteRule *rules;\n"
"    int          nrules;\n"
"    int          caprules;\n"
"    size_t       pos;\n"
"};\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Drivers\n"
" *\n"
" *     %driver c = typecheck, emit-c -> out .\n"
" *\n"
" * Passes in order, and which attribute of the root is the answer. A driver\n"
" * with no `->` is a validation run: nothing is printed and the exit status is\n"
" * the whole of what it says.\n"
" *\n"
" * Attributes stay on the nodes between passes, which is what makes a sequence\n"
" * worth having -- `typecheck` leaves `type` behind and `emit-c` reads it,\n"
" * without either knowing the other exists.\n"
" */\n"
"\n"
"struct Driver {\n"
"    char   *name;\n"
"    char  **passes;      /* by name, in the order they run */\n"
"    int     npasses;\n"
"    char   *answer;      /* the root attribute to print, or NULL */\n"
"    size_t  pos;\n"
"    size_t *pass_pos;    /* where each was named, for messages */\n"
"};\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Tokens\n"
" *\n"
" * The lexical half takes the longest match over every token rule, which is\n"
" * what a lexer does and what makes `\"<\" | \"<=\"` a question nobody has to\n"
" * answer. Ties go to the rule declared first.\n"
" */\n"
"\n"
"typedef struct {\n"
"    int         kind;   /* the lexical rule that matched                    */\n"
"    const char *text;\n"
"    size_t      len;\n"
"    size_t      pos;\n"
"} Token;\n"
"\n"
"typedef struct {\n"
"    Token *items;\n"
"    int    n;\n"
"    int    cap;\n"
"} Tokens;\n"
"\n"
"bool lex_run(Arena *a, const Grammar *g, const Source *src, Tokens *out);\n"
"\n"
"/* Whether the lexical half can produce this exact text as one whole token.\n"
" * Asked of every literal in the syntactic half, so that a grammar naming a\n"
" * `\",\"` no token rule spells is refused when it is read rather than when a\n"
" * file first happens to contain a comma. */\n"
"bool lex_produces(const Grammar *g, const char *text, size_t len);\n"
"void tokens_dump(FILE *out, const Grammar *g, const Source *src, const Tokens *t);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* The tree a file becomes\n"
" *\n"
" * A value is one of three things, and which one a rule answers follows a\n"
" * single rule with no exceptions: **a body that produced one value answers\n"
" * that value; a body that produced any other number answers a node named after\n"
" * the rule, holding them.**\n"
" *\n"
" * That is worth stating plainly because of what falls out of it. A chain of\n"
" * rules that each pass one thing along -- `expression` to `term` to `factor`\n"
" * to a number -- collapses to the number, without anybody saying so. The\n"
" * useless interior nodes that every hand-written tree-builder exists to strip\n"
" * are never built.\n"
" */\n"
"\n"
"typedef enum {\n"
"    V_NODE,    /* a named node with named fields                            */\n"
"    V_TEXT,    /* bytes -- what a token was spelled with, or any text       */\n"
"    V_LIST,    /* several values in order                                   */\n"
"    V_INT,     /* 64-bit signed                                             */\n"
"    V_FLOAT,   /* IEEE 754 binary64                                         */\n"
"    V_BOOL,\n"
"    V_NIL,     /* absence, and nothing else                                 */\n"
"    V_ERROR    /* internal: a failure already reported, propagating quietly  */\n"
"} VKind;\n"
"\n"
"typedef struct Value Value;\n"
"struct Value {\n"
"    VKind         kind;\n"
"    const char   *type;    /* V_NODE: its name                             */\n"
"    const char   *text;    /* V_TEXT: its bytes                            */\n"
"    size_t        len;\n"
"\n"
"    /* Where this came from: the first byte of its first token, and the last\n"
"     * byte of its last. A node is a **stretch** of source and not a point,\n"
"     * which matters wherever something is emitted *after* the things it is\n"
"     * about -- a send's own bytes go in after its arguments, so the line they\n"
"     * belong to is where the argument list ends. */\n"
"    size_t        pos;\n"
"    size_t        endpos;\n"
"    const char  **fields;  /* V_NODE: one name per kid, or NULL throughout  */\n"
"    Value       **items;\n"
"    int           n;\n"
"    long long     ival;    /* V_INT, V_BOOL                                */\n"
"    double        real;    /* V_FLOAT                                      */\n"
"    void         *attrs;   /* V_NODE: what a pass has worked out about it  */\n"
"};\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Evaluating an expression\n"
" *\n"
" * One evaluator, used by both halves. A stage-1 action resolves `$2` against\n"
" * the factors of a sequence; a stage-2 clause resolves `$name` against what its\n"
" * pattern bound. Everything between those two ends -- the arithmetic, the\n"
" * comparisons, the formatting -- is the same code, because two evaluators of\n"
" * one notation would be two things to keep in agreement and the project has\n"
" * enough of those already.\n"
" */\n"
"\n"
"typedef struct Eval Eval;\n"
"struct Eval {\n"
"    Arena         *a;\n"
"    const Grammar *g;\n"
"    Value       *(*ref)(Eval *, const Expr *);   /* $n, $name, $$, x.attr   */\n"
"    void          *data;                          /* whatever ref needs      */\n"
"    size_t         pos;   /* where in the *source* a node built here belongs */\n"
"    size_t         endpos;/* and where it ends -- see Value.endpos           */\n"
"};\n"
"\n"
"Value *eval_expr(Eval *e, const Expr *x);\n"
"\n"
"/* The functions a pass may call -- library.c, kept separate so that the\n"
" * question of where the library stops stays a visible one. */\n"
"Value *eval_call(Eval *e, const Expr *x);\n"
"\n"
"Value *value_int(Arena *a, long long n);\n"
"Value *value_float(Arena *a, double d);\n"
"Value *value_bool(Arena *a, bool b);\n"
"Value *value_nil(Arena *a);\n"
"\n"
"/* A failure that has already been reported. Every operation on one answers\n"
" * another, silently -- so one mistake in a pass produces one message rather\n"
" * than one message and four consequences of it. */\n"
"Value *value_error(Arena *a);\n"
"bool   value_failed(const Value *v);\n"
"Value *value_text(Arena *a, const char *text, size_t len);\n"
"\n"
"/* Writes a value the way `of` writes it -- see docs/semantics.md. Answers\n"
" * false, having reported, for the kinds that refuse to be written. */\n"
"bool value_format(Arena *a, const Value *v, char **out, size_t *len);\n"
"\n"
"const char *value_kind_name(const Value *v);\n"
"\n"
"/* Structural equality -- the same `=` answers, so that everything comparing\n"
" * values compares them the one way. */\n"
"bool value_equal(const Value *a, const Value *b);\n"
"\n"
"/* Matches the tokens against the grammar. Answers NULL on a syntax error,\n"
" * having reported where the match got furthest and what it wanted there. */\n"
"Value *parse_run(Arena *a, const Grammar *g, const Source *src, const Tokens *t);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* A target language's own includes -- include.c\n"
" *\n"
" * `%import` splices one description into another. This is the same thing one\n"
" * level down, for the language being described, and it is a separate mechanism\n"
" * for a reason that is not arbitrary: **a pass cannot do it.** A pass is a walk\n"
" * over one tree that has already been read, and an include is a second file\n"
" * that has to be read before there is a tree to walk at all.\n"
" *\n"
" * So this runs between the parser and the first pass, and every pass after it\n"
" * sees one tree that never mentions a second file.\n"
" */\n"
"\n"
"typedef struct {\n"
"    const char **dirs;\n"
"    int          n;\n"
"    int          cap;\n"
"} IncludePath;\n"
"\n"
"/* `-I dir`, in the order given: the first directory holding a file wins. */\n"
"void include_path_add(Arena *a, IncludePath *look, const char *dir);\n"
"\n"
"/* Replaces every include node in `root` with what the file it names holds.\n"
" * `src` grows as files are read, so that a position in an included file still\n"
" * names its own file and line; the tree is edited in place. Answers false\n"
" * having reported. Does nothing at all when the description declares no\n"
" * `%include`. */\n"
"bool include_expand(Arena *a, const Grammar *g, Source *src,\n"
"                    const IncludePath *look, Value *root);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Counting the work\n"
" *\n"
" * A PEG with no memoisation can do more work than there is input, and how much\n"
" * more is a property of the grammar rather than of the machine. These say how\n"
" * much was actually done, so that a curve can be explained and not merely\n"
" * drawn: `steps` is one attempt to match one grammar node at one position.\n"
" */\n"
"\n"
"typedef struct {\n"
"    long long lex_steps;     /* attempts in the scanner   */\n"
"    long long parse_steps;   /* attempts in the matcher   */\n"
"    long long nodes;         /* values the tree came to   */\n"
"    int       depth;         /* how deep the matcher went */\n"
"} Work;\n"
"\n"
"const Work *work_done(void);\n"
"void        work_reset(void);\n"
"\n"
"void tree_dump(FILE *out, const Value *root);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Running a pass -- run.c */\n"
"\n"
"const Pass   *pass_find(const Grammar *g, const char *name);\n"
"const Driver *driver_find(const Grammar *g, const char *name);\n"
"\n"
"/* The driver to run when none is named: the first one declared in the file\n"
" * that was asked for, and only failing that the first declared anywhere. A\n"
" * description that imports another must not inherit its default -- the file\n"
" * you named is the one that says what it is for. */\n"
"const Driver *driver_default(const Grammar *g);\n"
"\n"
"/* One walk, post-order. Answers false having reported. */\n"
"bool pass_run(Arena *a, const Grammar *g, const Source *src,\n"
"              const Pass *pass, Value *root);\n"
"\n"
"/* What a pass worked out about a node, or NULL. */\n"
"Value *pass_attr(const Value *node, const char *name);\n"
"\n"
"const Rewrite *rewrite_find(const Grammar *g, const char *name);\n"
"\n"
"/* One walk, replacing. The root itself may be replaced, which is why the tree\n"
" * arrives by reference. Answers false having reported. */\n"
"bool rewrite_run(Arena *a, const Grammar *g, const Source *src,\n"
"                 const Rewrite *rw, Value **root);\n"
"\n"
"/* One stage of a driver, whichever kind it is. Answers false having reported;\n"
" * `*root` is what the next stage should walk. */\n"
"bool driver_stage(Arena *a, const Grammar *g, const Source *src,\n"
"                  const char *name, Value **root);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Writing a description out as its own compiler -- emit.c */\n"
"\n"
"bool emit_compiler(const Grammar *g, const char *name, FILE *out);\n"
"\n"
"#endif /* PHX_H */\n"
"/* support.c -- the arena, the source file, and the messages.\n"
" *\n"
" * Nothing here knows what a grammar is.\n"
" */\n"
"\n"
"#include <stdarg.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Arena\n"
" *\n"
" * A list of blocks. A request larger than a block gets a block of its own, so\n"
" * that one big allocation cannot waste the rest of a shared one.\n"
" */\n"
"\n"
"#define ARENA_BLOCK (64 * 1024)\n"
"\n"
"typedef struct Block Block;\n"
"struct Block {\n"
"    Block  *next;\n"
"    size_t  used;\n"
"    size_t  size;\n"
"    char    data[];\n"
"};\n"
"\n"
"struct Arena {\n"
"    Block *head;\n"
"};\n"
"\n"
"Arena *arena_new(void)\n"
"{\n"
"    Arena *a = calloc(1, sizeof *a);\n"
"    if (!a) {\n"
"        fputs(\"phx: out of memory\\n\", stderr);\n"
"        exit(2);\n"
"    }\n"
"    return a;\n"
"}\n"
"\n"
"void arena_free(Arena *a)\n"
"{\n"
"    if (!a) return;\n"
"    for (Block *b = a->head; b; ) {\n"
"        Block *next = b->next;\n"
"        free(b);\n"
"        b = next;\n"
"    }\n"
"    free(a);\n"
"}\n"
"\n"
"void *arena_alloc(Arena *a, size_t n)\n"
"{\n"
"    n = (n + 15) & ~(size_t)15;          /* keep everything 16-byte aligned */\n"
"\n"
"    if (!a->head || a->head->used + n > a->head->size) {\n"
"        size_t size = n > ARENA_BLOCK ? n : ARENA_BLOCK;\n"
"        Block *b = calloc(1, sizeof *b + size);\n"
"        if (!b) {\n"
"            fputs(\"phx: out of memory\\n\", stderr);\n"
"            exit(2);\n"
"        }\n"
"        b->size = size;\n"
"        b->next = a->head;\n"
"        a->head = b;\n"
"    }\n"
"\n"
"    void *p = a->head->data + a->head->used;\n"
"    a->head->used += n;\n"
"    return p;\n"
"}\n"
"\n"
"char *arena_strndup(Arena *a, const char *s, size_t n)\n"
"{\n"
"    char *p = arena_alloc(a, n + 1);\n"
"    memcpy(p, s, n);\n"
"    p[n] = '\\0';\n"
"    return p;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Source */\n"
"\n"
"static bool read_into(Arena *a, const char *path, Source *out, bool complain)\n"
"{\n"
"    memset(out, 0, sizeof *out);      /* `map` in particular: callers use the stack */\n"
"\n"
"    FILE *f = fopen(path, \"rb\");\n"
"    if (!f) {\n"
"        if (complain) fprintf(stderr, \"phx: cannot read %s\\n\", path);\n"
"        return false;\n"
"    }\n"
"\n"
"    size_t cap = 8192, size = 0;\n"
"    char  *buf = arena_alloc(a, cap);\n"
"\n"
"    for (;;) {\n"
"        if (size == cap) {\n"
"            char *bigger = arena_alloc(a, cap * 2);\n"
"            memcpy(bigger, buf, size);\n"
"            buf = bigger;\n"
"            cap *= 2;\n"
"        }\n"
"        size_t got = fread(buf + size, 1, cap - size, f);\n"
"        size += got;\n"
"        if (got == 0) break;\n"
"    }\n"
"    fclose(f);\n"
"\n"
"    buf[size] = '\\0';\n"
"    out->path = path;\n"
"    out->text = buf;\n"
"    out->size = size;\n"
"    return true;\n"
"}\n"
"\n"
"bool source_read(Arena *a, const char *path, Source *out)\n"
"{\n"
"    return read_into(a, path, out, true);\n"
"}\n"
"\n"
"bool source_try(Arena *a, const char *path, Source *out)\n"
"{\n"
"    return read_into(a, path, out, false);\n"
"}\n"
"\n"
"/* The stretch of the joined text an offset belongs to. */\n"
"static const Unit *unit_at(const Source *src, size_t off)\n"
"{\n"
"    if (!src->map) return NULL;\n"
"\n"
"    for (int i = src->map->n - 1; i >= 0; i--)\n"
"        if (off >= src->map->units[i].start) return &src->map->units[i];\n"
"\n"
"    return src->map->n ? &src->map->units[0] : NULL;\n"
"}\n"
"\n"
"const char *source_path_at(const Source *src, size_t off)\n"
"{\n"
"    const Unit *u = unit_at(src, off);\n"
"    return u ? u->path : src->path;\n"
"}\n"
"\n"
"void source_position(const Source *src, size_t off, int *line, int *col)\n"
"{\n"
"    if (off > src->size) off = src->size;\n"
"\n"
"    /* Lines are counted from the start of the file the offset is in, not from\n"
"     * the start of the joined text -- otherwise an imported file's line\n"
"     * numbers would be its position in a buffer nobody wrote. */\n"
"    const Unit *u    = unit_at(src, off);\n"
"    size_t      from = u ? u->start : 0;\n"
"\n"
"    int    ln    = 1;\n"
"    size_t start = from;\n"
"    for (size_t i = from; i < off; i++) {\n"
"        if (src->text[i] == '\\n') {\n"
"            ln++;\n"
"            start = i + 1;\n"
"        }\n"
"    }\n"
"    *line = ln;\n"
"    *col  = (int)(off - start) + 1;\n"
"}\n"
"\n"
"void source_line(const Source *src, size_t off, const char **start, size_t *len)\n"
"{\n"
"    if (off > src->size) off = src->size;\n"
"\n"
"    /* A line never runs past the end of the file it is in. */\n"
"    const Unit *u    = unit_at(src, off);\n"
"    size_t      from = u ? u->start : 0;\n"
"    size_t      to   = u ? u->start + u->size : src->size;\n"
"    if (to > src->size) to = src->size;\n"
"\n"
"    size_t a = off;\n"
"    while (a > from && src->text[a - 1] != '\\n') a--;\n"
"\n"
"    size_t b = a;\n"
"    while (b < to && src->text[b] != '\\n') b++;\n"
"\n"
"    *start = src->text + a;\n"
"    *len   = b - a;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Diagnostics */\n"
"\n"
"static int errors;\n"
"\n"
"static void report(const char *kind, const Source *src, size_t off,\n"
"                   const char *fmt, va_list ap)\n"
"{\n"
"    if (src) {\n"
"        int line, col;\n"
"        source_position(src, off, &line, &col);\n"
"        fprintf(stderr, \"%s:%d:%d: %s: \",\n"
"                source_path_at(src, off), line, col, kind);\n"
"    } else {\n"
"        fprintf(stderr, \"phx: %s: \", kind);\n"
"    }\n"
"\n"
"    vfprintf(stderr, fmt, ap);\n"
"    fputc('\\n', stderr);\n"
"\n"
"    if (src) {\n"
"        const char *start;\n"
"        size_t      len;\n"
"        source_line(src, off, &start, &len);\n"
"\n"
"        int line, col;\n"
"        source_position(src, off, &line, &col);\n"
"\n"
"        fprintf(stderr, \"  %.*s\\n  \", (int)len, start);\n"
"        for (int i = 1; i < col; i++)\n"
"            fputc(start[i - 1] == '\\t' ? '\\t' : ' ', stderr);\n"
"        fputs(\"^\\n\", stderr);\n"
"    }\n"
"}\n"
"\n"
"void diag_error(const Source *src, size_t off, const char *fmt, ...)\n"
"{\n"
"    va_list ap;\n"
"    va_start(ap, fmt);\n"
"    report(\"error\", src, off, fmt, ap);\n"
"    va_end(ap);\n"
"    errors++;\n"
"}\n"
"\n"
"void diag_warn(const Source *src, size_t off, const char *fmt, ...)\n"
"{\n"
"    va_list ap;\n"
"    va_start(ap, fmt);\n"
"    report(\"warning\", src, off, fmt, ap);\n"
"    va_end(ap);\n"
"}\n"
"\n"
"void diag_note(const char *fmt, ...)\n"
"{\n"
"    va_list ap;\n"
"    va_start(ap, fmt);\n"
"    fputs(\"phx: \", stderr);\n"
"    vfprintf(stderr, fmt, ap);\n"
"    fputc('\\n', stderr);\n"
"    va_end(ap);\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Counting the work */\n"
"\n"
"Work phx_work;\n"
"\n"
"const Work *work_done(void) { return &phx_work; }\n"
"void        work_reset(void) { phx_work = (Work){ 0 }; }\n"
"\n"
"bool diag_failed(void) { return errors > 0; }\n"
"int  diag_errors(void) { return errors; }\n"
"/* eval.c -- what an expression in the meta-language answers.\n"
" *\n"
" * docs/semantics.md is the specification and this file is what makes it true;\n"
" * the two are changed together or not at all. Every rule that page states --\n"
" * checked integers, floored division, no implicit conversion, structural\n"
" * equality, left-to-right order -- is enforced here rather than borrowed from\n"
" * C, so that a second backend has something exact to agree with.\n"
" */\n"
"\n"
"#include <limits.h>\n"
"#include <math.h>\n"
"#include <stdarg.h>\n"
"#include <stdio.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Making values */\n"
"\n"
"static Value *fresh(Arena *a, VKind kind)\n"
"{\n"
"    Value *v = arena_alloc(a, sizeof *v);\n"
"    v->kind  = kind;\n"
"    return v;\n"
"}\n"
"\n"
"Value *value_int(Arena *a, long long n)   { Value *v = fresh(a, V_INT);   v->ival = n; return v; }\n"
"Value *value_float(Arena *a, double d)    { Value *v = fresh(a, V_FLOAT); v->real = d; return v; }\n"
"Value *value_bool(Arena *a, bool b)       { Value *v = fresh(a, V_BOOL);  v->ival = b; return v; }\n"
"Value *value_nil(Arena *a)                { return fresh(a, V_NIL); }\n"
"Value *value_error(Arena *a)              { return fresh(a, V_ERROR); }\n"
"bool   value_failed(const Value *v)       { return v && v->kind == V_ERROR; }\n"
"\n"
"Value *value_text(Arena *a, const char *text, size_t len)\n"
"{\n"
"    Value *v = fresh(a, V_TEXT);\n"
"    v->text  = text;\n"
"    v->len   = len;\n"
"    return v;\n"
"}\n"
"\n"
"const char *value_kind_name(const Value *v)\n"
"{\n"
"    switch (v->kind) {\n"
"    case V_NODE:  return v->type ? v->type : \"node\";\n"
"    case V_TEXT:  return \"text\";\n"
"    case V_LIST:  return \"list\";\n"
"    case V_INT:   return \"integer\";\n"
"    case V_FLOAT: return \"float\";\n"
"    case V_BOOL:  return \"boolean\";\n"
"    case V_NIL:   return \"nil\";\n"
"    case V_ERROR: return \"a failure\";\n"
"    }\n"
"    return \"value\";\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Writing a value, the way `of` writes it */\n"
"\n"
"/* The shortest decimal that reads back as the same double. Trying each\n"
" * precision in turn is not clever, and it is exact and identical everywhere,\n"
" * which is what the conformance rule needs. */\n"
"static int format_float(double d, char *buf, size_t size)\n"
"{\n"
"    if (isnan(d))      return snprintf(buf, size, \"nan\");\n"
"    if (isinf(d))      return snprintf(buf, size, d < 0 ? \"-infinity\" : \"infinity\");\n"
"\n"
"    for (int digits = 1; digits <= 17; digits++) {\n"
"        int wrote = snprintf(buf, size, \"%.*g\", digits, d);\n"
"        if (wrote > 0 && (size_t)wrote < size && strtod(buf, NULL) == d) return wrote;\n"
"    }\n"
"    return snprintf(buf, size, \"%.17g\", d);\n"
"}\n"
"\n"
"bool value_format(Arena *a, const Value *v, char **out, size_t *len)\n"
"{\n"
"    char buf[64];\n"
"    int  wrote;\n"
"\n"
"    switch (v->kind) {\n"
"    case V_TEXT:\n"
"        *out = (char *)v->text;\n"
"        *len = v->len;\n"
"        return true;\n"
"\n"
"    case V_INT:   wrote = snprintf(buf, sizeof buf, \"%lld\", v->ival);   break;\n"
"    case V_BOOL:  wrote = snprintf(buf, sizeof buf, \"%s\", v->ival ? \"true\" : \"false\"); break;\n"
"    case V_FLOAT: wrote = format_float(v->real, buf, sizeof buf);       break;\n"
"\n"
"    case V_ERROR:\n"
"        return false;\n"
"    case V_NIL:\n"
"        diag_note(\"nil has no written form -- a pass that wants one says what it is\");\n"
"        return false;\n"
"    case V_NODE:\n"
"    case V_LIST:\n"
"        diag_note(\"a %s has no written form -- a pass that wants one says what it is\",\n"
"                  value_kind_name(v));\n"
"        return false;\n"
"    }\n"
"\n"
"    *out = arena_strndup(a, buf, (size_t)wrote);\n"
"    *len = (size_t)wrote;\n"
"    return true;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Structural equality\n"
" *\n"
" * Two values are equal when they are indistinguishable, all the way down.\n"
" * Different kinds are unequal rather than an error, so that a guard may ask\n"
" * `$x = nil` without knowing what `$x` is.\n"
" */\n"
"\n"
"bool value_equal(const Value *a, const Value *b)\n"
"{\n"
"    if (a->kind != b->kind) return false;\n"
"\n"
"    switch (a->kind) {\n"
"    case V_ERROR:\n"
"    case V_NIL:   return true;\n"
"    case V_BOOL:\n"
"    case V_INT:   return a->ival == b->ival;\n"
"    case V_FLOAT: return a->real == b->real;   /* nan is unequal to itself */\n"
"    case V_TEXT:  return a->len == b->len && memcmp(a->text, b->text, a->len) == 0;\n"
"\n"
"    case V_LIST:\n"
"        if (a->n != b->n) return false;\n"
"        for (int i = 0; i < a->n; i++)\n"
"            if (!value_equal(a->items[i], b->items[i])) return false;\n"
"        return true;\n"
"\n"
"    case V_NODE:\n"
"        if (a->n != b->n) return false;\n"
"        if (!a->type || !b->type || strcmp(a->type, b->type) != 0) return false;\n"
"        for (int i = 0; i < a->n; i++) {\n"
"            const char *fa = a->fields ? a->fields[i] : NULL;\n"
"            const char *fb = b->fields ? b->fields[i] : NULL;\n"
"            if ((fa == NULL) != (fb == NULL)) return false;\n"
"            if (fa && strcmp(fa, fb) != 0) return false;\n"
"            if (!value_equal(a->items[i], b->items[i])) return false;\n"
"        }\n"
"        return true;\n"
"    }\n"
"    return false;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Arithmetic\n"
" *\n"
" * Integers are checked, and floored where the spec says floored. Every one of\n"
" * these could have been one C operator; none of them is, because C's answers\n"
" * are not the ones docs/semantics.md promises.\n"
" */\n"
"\n"
"static bool add_checked(long long a, long long b, long long *out)\n"
"{\n"
"    return !__builtin_add_overflow(a, b, out);\n"
"}\n"
"static bool sub_checked(long long a, long long b, long long *out)\n"
"{\n"
"    return !__builtin_sub_overflow(a, b, out);\n"
"}\n"
"static bool mul_checked(long long a, long long b, long long *out)\n"
"{\n"
"    return !__builtin_mul_overflow(a, b, out);\n"
"}\n"
"\n"
"/* Floored, so that `a mod b` carries the sign of `b`. C truncates, so the\n"
" * quotient is corrected when the signs differ and the division was not exact. */\n"
"static bool div_floored(long long a, long long b, long long *out)\n"
"{\n"
"    if (b == 0) return false;\n"
"    if (a == LLONG_MIN && b == -1) return false;      /* the one that traps */\n"
"\n"
"    long long q = a / b, r = a % b;\n"
"    if (r != 0 && ((r < 0) != (b < 0))) q--;\n"
"    *out = q;\n"
"    return true;\n"
"}\n"
"\n"
"static bool mod_floored(long long a, long long b, long long *out)\n"
"{\n"
"    if (b == 0) return false;\n"
"    if (a == LLONG_MIN && b == -1) { *out = 0; return true; }\n"
"\n"
"    long long r = a % b;\n"
"    if (r != 0 && ((r < 0) != (b < 0))) r += b;\n"
"    *out = r;\n"
"    return true;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"static Value *eval_fail(Eval *e, const Expr *x, const char *fmt, ...)\n"
"{\n"
"    va_list ap;\n"
"    va_start(ap, fmt);\n"
"\n"
"    char message[512];\n"
"    vsnprintf(message, sizeof message, fmt, ap);\n"
"    va_end(ap);\n"
"\n"
"    diag_error(&e->g->src, x->pos, \"%s\", message);\n"
"    return NULL;\n"
"}\n"
"\n"
"static Value *arith(Eval *e, const Expr *x, Value *l, Value *r)\n"
"{\n"
"    const char *op = x->name;\n"
"\n"
"    if (value_failed(l)) return l;\n"
"    if (value_failed(r)) return r;\n"
"\n"
"    /* No implicit conversion, anywhere. This is the rule that most protects\n"
"     * two backends from disagreeing, so it is checked before anything else. */\n"
"    if (l->kind != r->kind)\n"
"        return eval_fail(e, x, \"'%s' between %s and %s -- there is no conversion, \"\n"
"                          \"so write int() or float()\",\n"
"                    op, value_kind_name(l), value_kind_name(r));\n"
"\n"
"    if (l->kind == V_TEXT && strcmp(op, \"+\") == 0)\n"
"        return eval_fail(e, x, \"'+' does not join text -- write \\\"{}{}\\\" of a, b\");\n"
"\n"
"    if (l->kind == V_INT) {\n"
"        long long out;\n"
"        bool ok;\n"
"\n"
"        if      (strcmp(op, \"+\")   == 0) ok = add_checked(l->ival, r->ival, &out);\n"
"        else if (strcmp(op, \"-\")   == 0) ok = sub_checked(l->ival, r->ival, &out);\n"
"        else if (strcmp(op, \"*\")   == 0) ok = mul_checked(l->ival, r->ival, &out);\n"
"        else if (strcmp(op, \"div\") == 0\n"
"              || strcmp(op, \"/\")   == 0) ok = div_floored(l->ival, r->ival, &out);\n"
"        else if (strcmp(op, \"mod\") == 0) ok = mod_floored(l->ival, r->ival, &out);\n"
"        else return eval_fail(e, x, \"'%s' is not arithmetic\", op);\n"
"\n"
"        if (!ok) {\n"
"            if ((strcmp(op, \"div\") == 0 || strcmp(op, \"/\") == 0\n"
"                 || strcmp(op, \"mod\") == 0) && r->ival == 0)\n"
"                return eval_fail(e, x, \"division by zero\");\n"
"            return eval_fail(e, x, \"this overflows a 64-bit integer\");\n"
"        }\n"
"        return value_int(e->a, out);\n"
"    }\n"
"\n"
"    if (l->kind == V_FLOAT) {\n"
"        double out;\n"
"        if      (strcmp(op, \"+\") == 0) out = l->real + r->real;\n"
"        else if (strcmp(op, \"-\") == 0) out = l->real - r->real;\n"
"        else if (strcmp(op, \"*\") == 0) out = l->real * r->real;\n"
"        else if (strcmp(op, \"/\") == 0) out = l->real / r->real;  /* IEEE: inf */\n"
"        else return eval_fail(e, x, \"'%s' is integer arithmetic; this is a float\", op);\n"
"        return value_float(e->a, out);\n"
"    }\n"
"\n"
"    return eval_fail(e, x, \"'%s' wants numbers, and this is %s\",\n"
"                op, value_kind_name(l));\n"
"}\n"
"\n"
"static Value *compare(Eval *e, const Expr *x, Value *l, Value *r)\n"
"{\n"
"    const char *op = x->name;\n"
"\n"
"    if (value_failed(l)) return l;\n"
"    if (value_failed(r)) return r;\n"
"\n"
"    if (strcmp(op, \"=\")  == 0) return value_bool(e->a,  value_equal(l, r));\n"
"    if (strcmp(op, \"<>\") == 0) return value_bool(e->a, !value_equal(l, r));\n"
"\n"
"    /* Ordering is within a kind only: across kinds there is no order anyone\n"
"     * would agree on, and agreeing is the whole job. */\n"
"    if (l->kind != r->kind)\n"
"        return eval_fail(e, x, \"'%s' between %s and %s -- there is no order across kinds\",\n"
"                    op, value_kind_name(l), value_kind_name(r));\n"
"\n"
"    int sign;\n"
"    switch (l->kind) {\n"
"    case V_INT:   sign = l->ival < r->ival ? -1 : l->ival > r->ival ? 1 : 0; break;\n"
"    case V_FLOAT:\n"
"        if (isnan(l->real) || isnan(r->real)) return value_bool(e->a, false);\n"
"        sign = l->real < r->real ? -1 : l->real > r->real ? 1 : 0;\n"
"        break;\n"
"    case V_TEXT: {\n"
"        size_t n = l->len < r->len ? l->len : r->len;\n"
"        int    c = memcmp(l->text, r->text, n);\n"
"        sign = c < 0 ? -1 : c > 0 ? 1 : (l->len < r->len ? -1 : l->len > r->len);\n"
"        break;\n"
"    }\n"
"    default:\n"
"        return eval_fail(e, x, \"'%s' does not order a %s\", op, value_kind_name(l));\n"
"    }\n"
"\n"
"    if (strcmp(op, \"<\")  == 0) return value_bool(e->a, sign <  0);\n"
"    if (strcmp(op, \">\")  == 0) return value_bool(e->a, sign >  0);\n"
"    if (strcmp(op, \"<=\") == 0) return value_bool(e->a, sign <= 0);\n"
"    if (strcmp(op, \">=\") == 0) return value_bool(e->a, sign >= 0);\n"
"\n"
"    return eval_fail(e, x, \"'%s' is not a comparison\", op);\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Formatting */\n"
"\n"
"static Value *format(Eval *e, const Expr *x)\n"
"{\n"
"    Value *template = eval_expr(e, x->kids[0]);\n"
"    if (!template) return NULL;\n"
"\n"
"    if (value_failed(template)) return template;\n"
"\n"
"    if (template->kind != V_TEXT)\n"
"        return eval_fail(e, x, \"'of' fills text, and this is %s\",\n"
"                    value_kind_name(template));\n"
"\n"
"    size_t cap  = template->len + 64;\n"
"    char  *buf  = arena_alloc(e->a, cap);\n"
"    size_t used = 0;\n"
"    int    next = 1;\n"
"\n"
"    for (size_t i = 0; i < template->len; i++) {\n"
"        char c = template->text[i];\n"
"\n"
"        /* `{{` and `}}` are the braces themselves. */\n"
"        if ((c == '{' || c == '}') && i + 1 < template->len\n"
"            && template->text[i + 1] == c) {\n"
"            i++;\n"
"        } else if (c == '{' && i + 1 < template->len && template->text[i + 1] == '}') {\n"
"            if (next >= x->nkids)\n"
"                return eval_fail(e, x, \"this template has more {} than there are values\");\n"
"\n"
"            Value *arg = eval_expr(e, x->kids[next++]);\n"
"            if (!arg) return NULL;\n"
"            if (value_failed(arg)) return arg;\n"
"\n"
"            char  *text;\n"
"            size_t len;\n"
"            if (!value_format(e->a, arg, &text, &len))\n"
"                return eval_fail(e, x->kids[next - 1], \"a %s cannot fill a {}\",\n"
"                            value_kind_name(arg));\n"
"\n"
"            while (used + len + 1 > cap) {\n"
"                char *big = arena_alloc(e->a, cap * 2);\n"
"                memcpy(big, buf, used);\n"
"                buf = big;\n"
"                cap *= 2;\n"
"            }\n"
"            memcpy(buf + used, text, len);\n"
"            used += len;\n"
"            i++;\n"
"            continue;\n"
"        }\n"
"\n"
"        if (used + 2 > cap) {\n"
"            char *big = arena_alloc(e->a, cap * 2);\n"
"            memcpy(big, buf, used);\n"
"            buf = big;\n"
"            cap *= 2;\n"
"        }\n"
"        buf[used++] = c;\n"
"    }\n"
"\n"
"    if (next < x->nkids)\n"
"        return eval_fail(e, x, \"this template has %d {} and %d value%s were given\",\n"
"                    next - 1, x->nkids - 1, x->nkids == 2 ? \"\" : \"s\");\n"
"\n"
"    buf[used] = '\\0';\n"
"    return value_text(e->a, buf, used);\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"Value *eval_expr(Eval *e, const Expr *x)\n"
"{\n"
"    switch (x->kind) {\n"
"    case X_INT:   return value_int(e->a, x->ival);\n"
"    case X_FLOAT: return value_float(e->a, x->real);\n"
"    case X_BOOL:  return value_bool(e->a, x->ival != 0);\n"
"    case X_NIL:   return value_nil(e->a);\n"
"    case X_TEXT:  return value_text(e->a, x->name, (size_t)x->len);\n"
"\n"
"    case X_REF:\n"
"    case X_ACC:\n"
"    case X_DOT:\n"
"        return e->ref(e, x);\n"
"\n"
"    case X_UNOP: {\n"
"        Value *v = eval_expr(e, x->kids[0]);\n"
"        if (!v) return NULL;\n"
"\n"
"        if (value_failed(v)) return v;\n"
"\n"
"        if (strcmp(x->name, \"not\") == 0) {\n"
"            if (v->kind != V_BOOL)\n"
"                return eval_fail(e, x, \"'not' wants a boolean, and this is %s\",\n"
"                            value_kind_name(v));\n"
"            return value_bool(e->a, !v->ival);\n"
"        }\n"
"        if (v->kind == V_INT) {\n"
"            long long out;\n"
"            if (!sub_checked(0, v->ival, &out))\n"
"                return eval_fail(e, x, \"negating this overflows a 64-bit integer\");\n"
"            return value_int(e->a, out);\n"
"        }\n"
"        if (v->kind == V_FLOAT) return value_float(e->a, -v->real);\n"
"        return eval_fail(e, x, \"'-' wants a number, and this is %s\", value_kind_name(v));\n"
"    }\n"
"\n"
"    case X_BINOP: {\n"
"        /* `and` and `or` short-circuit, so their right side is not evaluated\n"
"         * before it is known to be needed. */\n"
"        if (strcmp(x->name, \"and\") == 0 || strcmp(x->name, \"or\") == 0) {\n"
"            Value *l = eval_expr(e, x->kids[0]);\n"
"            if (!l) return NULL;\n"
"            if (value_failed(l)) return l;\n"
"            if (l->kind != V_BOOL)\n"
"                return eval_fail(e, x, \"'%s' wants booleans, and the left is %s\",\n"
"                            x->name, value_kind_name(l));\n"
"\n"
"            bool want = x->name[0] == 'a';\n"
"            if ((bool)l->ival != want) return l;\n"
"\n"
"            Value *r = eval_expr(e, x->kids[1]);\n"
"            if (!r) return NULL;\n"
"            if (r->kind != V_BOOL)\n"
"                return eval_fail(e, x, \"'%s' wants booleans, and the right is %s\",\n"
"                            x->name, value_kind_name(r));\n"
"            return r;\n"
"        }\n"
"\n"
"        Value *l = eval_expr(e, x->kids[0]);\n"
"        if (!l) return NULL;\n"
"        Value *r = eval_expr(e, x->kids[1]);\n"
"        if (!r) return NULL;\n"
"\n"
"        switch (x->name[0]) {\n"
"        case '=': case '<': case '>':\n"
"            return compare(e, x, l, r);\n"
"        default:\n"
"            return arith(e, x, l, r);\n"
"        }\n"
"    }\n"
"\n"
"    case X_FORMAT:\n"
"        return format(e, x);\n"
"\n"
"    case X_LIST: {\n"
"        Value  *v     = fresh(e->a, V_LIST);\n"
"        int     cap   = x->nkids > 0 ? x->nkids : 1;\n"
"        Value **items = arena_alloc(e->a, (size_t)cap * sizeof *items);\n"
"        int     n     = 0;\n"
"\n"
"        for (int i = 0; i < x->nkids; i++) {\n"
"            const Expr *item = x->kids[i];\n"
"\n"
"            if (item->kind == X_SPREAD) {\n"
"                Value *inner = eval_expr(e, item->kids[0]);\n"
"                if (!inner) return NULL;\n"
"\n"
"                /* `...` of something that is not a list used to spread to\n"
"                 * the thing itself, which is quiet and wrong: `[$e, ...$3]`\n"
"                 * where `$3` is an item rather than a repetition then builds\n"
"                 * a two-element list out of one expression twice, and both\n"
"                 * the tree and everything written back from it are consistent\n"
"                 * about it. A real grammar had that bug for as long as this\n"
"                 * was allowed. Miscounting an item is the likeliest way to\n"
"                 * get here, so it is refused. */\n"
"                if (inner->kind != V_LIST)\n"
"                    return eval_fail(e, item, \"'...' wants a list, and this is %s\",\n"
"                                     value_kind_name(inner));\n"
"\n"
"                int add = inner->n;\n"
"                if (n + add > cap) {\n"
"                    cap = (n + add) * 2;\n"
"                    Value **big = arena_alloc(e->a, (size_t)cap * sizeof *big);\n"
"                    memcpy(big, items, (size_t)n * sizeof *big);\n"
"                    items = big;\n"
"                }\n"
"                for (int k = 0; k < inner->n; k++) items[n++] = inner->items[k];\n"
"                continue;\n"
"            }\n"
"\n"
"            Value *got = eval_expr(e, item);\n"
"            if (!got) return NULL;\n"
"\n"
"            if (n == cap) {\n"
"                cap *= 2;\n"
"                Value **big = arena_alloc(e->a, (size_t)cap * sizeof *big);\n"
"                memcpy(big, items, (size_t)n * sizeof *big);\n"
"                items = big;\n"
"            }\n"
"            items[n++] = got;\n"
"        }\n"
"        v->items = items;\n"
"        v->n     = n;\n"
"        return v;\n"
"    }\n"
"\n"
"    case X_NODE: {\n"
"        Value *v = fresh(e->a, V_NODE);\n"
"        v->type  = x->name;\n"
"        /* Where in the file being compiled this belongs -- not where in the\n"
"         * .phx the action that built it sits. A diagnostic from a later pass\n"
"         * points at the user's program, which is the only place worth\n"
"         * pointing at. */\n"
"        v->pos    = e->pos;\n"
"        v->endpos = e->endpos < e->pos ? e->pos : e->endpos;\n"
"\n"
"        if (x->nkids == 0) return v;\n"
"\n"
"        v->items  = arena_alloc(e->a, (size_t)x->nkids * sizeof *v->items);\n"
"        v->fields = arena_alloc(e->a, (size_t)x->nkids * sizeof *v->fields);\n"
"\n"
"        for (int i = 0; i < x->nkids; i++) {\n"
"            Value *got = eval_expr(e, x->kids[i]);\n"
"            if (!got) return NULL;\n"
"            v->items[i]  = got;\n"
"            v->fields[i] = x->fields[i];\n"
"        }\n"
"        v->n = x->nkids;\n"
"        return v;\n"
"    }\n"
"\n"
"    case X_CALL:\n"
"        return eval_call(e, x);\n"
"\n"
"    case X_SPREAD:\n"
"        return eval_fail(e, x, \"'...' belongs inside a list\");\n"
"    }\n"
"    return NULL;\n"
"}\n"
"/* library.c -- the functions a pass may call.\n"
" *\n"
" * Deliberately its own file, because the honest risk with a compiler generator\n"
" * is that its library grows without ever being decided about, and a library\n"
" * nobody drew a line around is a language nobody can reimplement. Every entry\n"
" * below is one a pass for the calculator or for Pascal actually needed; the\n"
" * moment one is added for a reason weaker than that, this file is the evidence.\n"
" *\n"
" * An **environment** is an association list -- a list of `[name, value]` pairs,\n"
" * most recent first. `bind` puts a pair on the front, so shadowing is what\n"
" * naturally happens and nobody implemented it. It is linear to look up, which\n"
" * is right for the sizes a compiler description works at and is a thing to\n"
" * revisit with measurements rather than with feelings.\n"
" */\n"
"\n"
"#include <limits.h>\n"
"#include <stdarg.h>\n"
"#include <stdlib.h>\n"
"#include <string.h>\n"
"\n"
"static Value *library_fail(Eval *e, const Expr *x, const char *fmt, ...)\n"
"{\n"
"    va_list ap;\n"
"    va_start(ap, fmt);\n"
"\n"
"    char message[512];\n"
"    vsnprintf(message, sizeof message, fmt, ap);\n"
"    va_end(ap);\n"
"\n"
"    diag_error(&e->g->src, x->pos, \"%s\", message);\n"
"    return NULL;\n"
"}\n"
"\n"
"static bool want(Eval *e, const Expr *x, int n, Value **args)\n"
"{\n"
"    if (x->nkids == n) return true;\n"
"\n"
"    diag_error(&e->g->src, x->pos, \"'%s' takes %d argument%s, and %d %s given\",\n"
"               x->name, n, n == 1 ? \"\" : \"s\", x->nkids,\n"
"               x->nkids == 1 ? \"was\" : \"were\");\n"
"    (void)args;\n"
"    return false;\n"
"}\n"
"\n"
"\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"static Value *list_of(Arena *a, Value **items, int n)\n"
"{\n"
"    Value *v = arena_alloc(a, sizeof *v);\n"
"    v->kind  = V_LIST;\n"
"    v->items = items;\n"
"    v->n     = n;\n"
"    return v;\n"
"}\n"
"\n"
"/* One number as `width` little-endian bytes. Split out when `bytes` learned to\n"
" * take a list, so that one number and a column of them cannot disagree. */\n"
"static Value *bytes_of(Eval *e, const Expr *x, Arena *a, const Value *n,\n"
"                       long long width)\n"
"{\n"
"    if (n->kind != V_INT && n->kind != V_FLOAT)\n"
"        return library_fail(e, x, \"'bytes' wants a number, and this is %s\",\n"
"                            value_kind_name(n));\n"
"\n"
"    /* A float is written as what it *is* -- its IEEE 754 bits -- which is\n"
"     * the only reading of \"this number as eight bytes\" a binary format\n"
"     * ever wants. Four bytes is single precision, and narrower is not a\n"
"     * float at all, so it is refused rather than quietly rounded. */\n"
"    unsigned long long v;\n"
"    if (n->kind == V_FLOAT) {\n"
"        if (width == 8) {\n"
"            double d = n->real;\n"
"            unsigned long long bits;\n"
"            memcpy(&bits, &d, sizeof bits);\n"
"            v = bits;\n"
"        } else if (width == 4) {\n"
"            float g = (float)n->real;\n"
"            unsigned int bits;\n"
"            memcpy(&bits, &g, sizeof bits);\n"
"            v = bits;\n"
"        } else {\n"
"            return library_fail(e, x, \"a float is four or eight bytes, not %lld\",\n"
"                                width);\n"
"        }\n"
"    } else {\n"
"        v = (unsigned long long)n->ival;\n"
"    }\n"
"\n"
"    char *out = arena_alloc(a, (size_t)width + 1);\n"
"    for (long long i = 0; i < width; i++) out[i] = (char)((v >> (8 * i)) & 0xff);\n"
"    out[width] = '\\0';\n"
"\n"
"    return value_text(a, out, (size_t)width);\n"
"}\n"
"\n"
"static Value *pair(Arena *a, Value *k, Value *v)\n"
"{\n"
"    Value **items = arena_alloc(a, 2 * sizeof *items);\n"
"    items[0] = k;\n"
"    items[1] = v;\n"
"    return list_of(a, items, 2);\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"Value *eval_call(Eval *e, const Expr *x)\n"
"{\n"
"    Arena *a    = e->a;\n"
"    Value *args[4];\n"
"    int    argc = x->nkids < 4 ? x->nkids : 4;\n"
"\n"
"    for (int i = 0; i < argc; i++) {\n"
"        args[i] = eval_expr(e, x->kids[i]);\n"
"        if (!args[i]) return NULL;\n"
"\n"
"        /* A failure passes straight through every function: it has already\n"
"         * been reported once, and once is the right number. */\n"
"        if (value_failed(args[i])) return args[i];\n"
"    }\n"
"    const char *f = x->name;\n"
"\n"
"    /* ---- environments ---- */\n"
"\n"
"    if (strcmp(f, \"empty\") == 0) {\n"
"        if (!want(e, x, 0, args)) return NULL;\n"
"        return list_of(a, NULL, 0);\n"
"    }\n"
"\n"
"    /* `bind` takes a name or a **list** of names, because `var a, b : integer`\n"
"     * binds two things to one type and writing that as two calls needs a fold\n"
"     * the notation has not got. Binding several is the same operation as\n"
"     * binding one, so it is the same function rather than a second. */\n"
"    if (strcmp(f, \"bind\") == 0) {\n"
"        if (!want(e, x, 3, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'bind' wants an environment, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"        if (args[1]->kind != V_TEXT && args[1]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'bind' wants a name or a list of names, \"\n"
"                                      \"and this is %s\", value_kind_name(args[1]));\n"
"\n"
"        int     adding = args[1]->kind == V_LIST ? args[1]->n : 1;\n"
"        int     n      = args[0]->n;\n"
"        Value **items  = arena_alloc(a, (size_t)(n + adding) * sizeof *items);\n"
"\n"
"        /* As many values as names binds them **pairwise**; one value binds\n"
"         * every name to it. Both are the same operation seen from different\n"
"         * sides, so both are `bind` rather than one being a second function. */\n"
"        bool pairwise = args[1]->kind == V_LIST && args[2]->kind == V_LIST\n"
"                        && args[2]->n == adding && adding > 0;\n"
"\n"
"        for (int i = 0; i < adding; i++) {\n"
"            Value *name = args[1]->kind == V_LIST ? args[1]->items[i] : args[1];\n"
"            if (name->kind != V_TEXT)\n"
"                return library_fail(e, x, \"'bind' wants text for a name, and one \"\n"
"                                          \"of these is %s\", value_kind_name(name));\n"
"            items[i] = pair(a, name, pairwise ? args[2]->items[i] : args[2]);\n"
"        }\n"
"        memcpy(items + adding, args[0]->items, (size_t)n * sizeof *items);\n"
"        return list_of(a, items, n + adding);\n"
"    }\n"
"\n"
"    /* `positions(list)` -- the table saying where each thing is, which is the\n"
"     * one fact about a list nothing else could reach: `at` wants an index and\n"
"     * nothing produced one. It is what turns a list of names into slots.\n"
"     *\n"
"     * Written as a table rather than as a list of indices so that it composes\n"
"     * with `lookup`, which is how every other question in the notation is\n"
"     * asked. A repeated element keeps its **first** position, matching what\n"
"     * `lookup` would answer for it. */\n"
"    if (strcmp(f, \"positions\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'positions' wants a list, and this is %s\",\n"
"                                value_kind_name(args[0]));\n"
"\n"
"        Value **items = arena_alloc(a, (size_t)args[0]->n * sizeof *items);\n"
"        int     n     = 0;\n"
"\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            bool seen = false;\n"
"            for (int j = 0; j < n; j++)\n"
"                if (value_equal(items[j]->items[0], args[0]->items[i])) { seen = true; break; }\n"
"            if (seen) continue;\n"
"            items[n++] = pair(a, args[0]->items[i], value_int(a, i));\n"
"        }\n"
"        return list_of(a, items, n);\n"
"    }\n"
"\n"
"    /* `lookup(env, name)` and `lookup(env, name, default)` -- the second is\n"
"     * the same operation with an answer for absence, and a notation with no\n"
"     * conditional needs one. */\n"
"    if (strcmp(f, \"lookup\") == 0 || strcmp(f, \"defined\") == 0) {\n"
"        bool defaulted = strcmp(f, \"lookup\") == 0 && x->nkids == 3;\n"
"        if (!defaulted && !want(e, x, 2, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'%s' wants an environment, and this is %s\",\n"
"                        f, value_kind_name(args[0]));\n"
"\n"
"        bool asking = f[0] == 'd';\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            const Value *entry = args[0]->items[i];\n"
"            if (entry->kind != V_LIST || entry->n != 2) continue;\n"
"            /* Compared the way `=` compares, not as text only. Text-only\n"
"             * meant an integer key never matched and never said so:\n"
"             * `lookup([[1, \"char\"]], size(t), \"string\")` quietly answered\n"
"             * \"string\" for every length. */\n"
"            if (value_equal(entry->items[0], args[1]))\n"
"                return asking ? value_bool(a, true) : entry->items[1];\n"
"        }\n"
"        if (asking)    return value_bool(a, false);\n"
"        if (defaulted) return args[2];\n"
"        return value_nil(a);\n"
"    }\n"
"\n"
"    /* ---- the other division ----\n"
"     *\n"
"     * `div` and `mod` are floored, which docs/semantics.md fixes and which is\n"
"     * right for Phoenix's own counting. **Target languages disagree with each\n"
"     * other about this**, and a pass that models one of them needs to say\n"
"     * which: C, Java and Pascal truncate toward zero, so `-7 / 2` is -3 there\n"
"     * and -4 here.\n"
"     *\n"
"     * These earn their place by the rule at the top of this file: without\n"
"     * them, an emit pass and an eval pass for the same language quietly\n"
"     * disagree about negative division, and the first anybody hears of it is\n"
"     * a compiled program answering differently from the interpreted one.\n"
"     * There is no way to write truncation in terms of flooring in a notation\n"
"     * with no conditional, which is the other half of why these are here. */\n"
"\n"
"    if (strcmp(f, \"quotient\") == 0 || strcmp(f, \"remainder\") == 0) {\n"
"        if (!want(e, x, 2, args)) return NULL;\n"
"        if (args[0]->kind != V_INT || args[1]->kind != V_INT)\n"
"            return library_fail(e, x, \"'%s' wants two integers, and got %s and %s\",\n"
"                        f, value_kind_name(args[0]), value_kind_name(args[1]));\n"
"\n"
"        long long n = args[0]->ival, d = args[1]->ival;\n"
"        if (d == 0) return library_fail(e, x, \"division by zero\");\n"
"        if (n == LLONG_MIN && d == -1)\n"
"            return library_fail(e, x, \"this overflows a 64-bit integer\");\n"
"\n"
"        return value_int(a, f[0] == 'q' ? n / d : n % d);   /* C truncates */\n"
"    }\n"
"\n"
"    /* ---- conversions ---- */\n"
"\n"
"    /* `int(text)` and `int(text, base)` -- the same operation with the base\n"
"     * said out loud, which a language whose literals carry a marker needs:\n"
"     * Solveig writes `#45`, `$ff` and `%1010` and they are one node. */\n"
"    if (strcmp(f, \"int\") == 0) {\n"
"        bool based = x->nkids == 2;\n"
"        if (!based && !want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind == V_INT) return args[0];\n"
"        if (args[0]->kind == V_FLOAT)\n"
"            return library_fail(e, x, \"'int' does not narrow a float -- \"\n"
"                              \"say floor, ceiling, round or truncate\");\n"
"        if (args[0]->kind != V_TEXT)\n"
"            return library_fail(e, x, \"'int' wants text, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"\n"
"        int base = 10;\n"
"        if (based) {\n"
"            if (args[1]->kind != V_INT || args[1]->ival < 2 || args[1]->ival > 36)\n"
"                return library_fail(e, x, \"'int' wants a base between 2 and 36\");\n"
"            base = (int)args[1]->ival;\n"
"        }\n"
"\n"
"        char *end;\n"
"        char *copy = arena_strndup(a, args[0]->text, args[0]->len);\n"
"        long long n = strtoll(copy, &end, base);\n"
"        if (end == copy || *end)\n"
"            return library_fail(e, x, \"\\\"%s\\\" is not an integer in base %d\",\n"
"                                copy, base);\n"
"        return value_int(a, n);\n"
"    }\n"
"\n"
"    if (strcmp(f, \"float\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind == V_FLOAT) return args[0];\n"
"        if (args[0]->kind == V_INT)   return value_float(a, (double)args[0]->ival);\n"
"        if (args[0]->kind != V_TEXT)\n"
"            return library_fail(e, x, \"'float' wants text or an integer, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"\n"
"        char *end;\n"
"        char *copy = arena_strndup(a, args[0]->text, args[0]->len);\n"
"        double d = strtod(copy, &end);\n"
"        if (end == copy || *end)\n"
"            return library_fail(e, x, \"\\\"%s\\\" is not a number\", copy);\n"
"        return value_float(a, d);\n"
"    }\n"
"\n"
"    if (strcmp(f, \"text\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        char  *out;\n"
"        size_t len;\n"
"        if (!value_format(a, args[0], &out, &len))\n"
"            return library_fail(e, x, \"a %s has no written form\", value_kind_name(args[0]));\n"
"        return value_text(a, out, len);\n"
"    }\n"
"\n"
"    if (strcmp(f, \"floor\") == 0 || strcmp(f, \"ceiling\") == 0\n"
"     || strcmp(f, \"round\") == 0 || strcmp(f, \"truncate\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind != V_FLOAT)\n"
"            return library_fail(e, x, \"'%s' wants a float, and this is %s\",\n"
"                        f, value_kind_name(args[0]));\n"
"\n"
"        double d = args[0]->real;\n"
"        double r = f[0] == 'f' ? __builtin_floor(d)\n"
"                 : f[0] == 'c' ? __builtin_ceil(d)\n"
"                 : f[0] == 'r' ? __builtin_round(d)\n"
"                               : __builtin_trunc(d);\n"
"\n"
"        if (!(r >= -9223372036854775808.0 && r < 9223372036854775808.0))\n"
"            return library_fail(e, x, \"%g does not fit a 64-bit integer\", d);\n"
"        return value_int(a, (long long)r);\n"
"    }\n"
"\n"
"    /* ---- bytes ----\n"
"     *\n"
"     * An integer as that many bytes, least significant first. **A description\n"
"     * that emits a binary format cannot do without it**, and it cannot be\n"
"     * written in the notation: there is no way to take a value apart into\n"
"     * bytes with arithmetic that answers integers and text that answers\n"
"     * characters.\n"
"     *\n"
"     * Little-endian and a width, because those are the two things a file\n"
"     * format fixes and the two things a caller must therefore say.\n"
"     *\n"
"     * A **list** of numbers answers a list of encodings, which is what a table\n"
"     * in a binary format is a column of.\n"
"     */\n"
"    if (strcmp(f, \"bytes\") == 0) {\n"
"        if (!want(e, x, 2, args)) return NULL;\n"
"        if (args[1]->kind != V_INT)\n"
"            return library_fail(e, x, \"'bytes' wants a number and a width\");\n"
"\n"
"        long long width = args[1]->ival;\n"
"        if (width < 1 || width > 8)\n"
"            return library_fail(e, x, \"'bytes' writes one to eight bytes, not %lld\",\n"
"                                width);\n"
"\n"
"        /* **A list of numbers answers a list of encodings**, which is the same\n"
"         * operation done as many times and not a second function. A table in a\n"
"         * binary format is a column of fixed-width numbers, and a description\n"
"         * that can say what the numbers are had no way to say them as bytes --\n"
"         * the row-by-row alternative is a clause on every node type that could\n"
"         * be a row, which is the same line of notation written twelve times.\n"
"         *\n"
"         * A *list* rather than the bytes joined together, because `join` is how\n"
"         * this notation concatenates and `each` is how it pairs two columns up.\n"
"         * Answering the concatenation would have been one function doing two\n"
"         * things. */\n"
"        if (args[0]->kind == V_LIST) {\n"
"            Value **items = arena_alloc(a, (size_t)(args[0]->n ? args[0]->n : 1)\n"
"                                             * sizeof *items);\n"
"            for (int i = 0; i < args[0]->n; i++) {\n"
"                Value *one = bytes_of(e, x, a, args[0]->items[i], width);\n"
"                if (!one) return NULL;\n"
"                items[i] = one;\n"
"            }\n"
"            return list_of(a, items, args[0]->n);\n"
"        }\n"
"        return bytes_of(e, x, a, args[0], width);\n"
"    }\n"
"\n"
"    /* ---- text ----\n"
"     *\n"
"     * Ordinary operations on bytes, and their absence was a real gap: a\n"
"     * Pascal string literal arrives with its quotes on and its doubled quotes\n"
"     * undoubled, and turning `'it''s'` into `\"it's\"` is\n"
"     * `join(split(slice(t, 2, size(t) - 1), \"''\"), \"'\")` and cannot be written\n"
"     * any other way here. One-based, both ends included, as everything in\n"
"     * this notation is. */\n"
"\n"
"    if (strcmp(f, \"slice\") == 0) {\n"
"        if (!want(e, x, 3, args)) return NULL;\n"
"        if (args[0]->kind != V_TEXT)\n"
"            return library_fail(e, x, \"'slice' wants text, and this is %s\",\n"
"                                value_kind_name(args[0]));\n"
"        if (args[1]->kind != V_INT || args[2]->kind != V_INT)\n"
"            return library_fail(e, x, \"'slice' wants two integers\");\n"
"\n"
"        long long from = args[1]->ival, to = args[2]->ival;\n"
"        if (from < 1) from = 1;\n"
"        if (to > (long long)args[0]->len) to = (long long)args[0]->len;\n"
"        if (to < from) return value_text(a, \"\", 0);\n"
"\n"
"        return value_text(a, args[0]->text + (from - 1), (size_t)(to - from + 1));\n"
"    }\n"
"\n"
"    if (strcmp(f, \"split\") == 0) {\n"
"        if (!want(e, x, 2, args)) return NULL;\n"
"        if (args[0]->kind != V_TEXT || args[1]->kind != V_TEXT)\n"
"            return library_fail(e, x, \"'split' wants text and text\");\n"
"        if (args[1]->len == 0)\n"
"            return library_fail(e, x, \"'split' cannot split on nothing\");\n"
"\n"
"        int cap = 8, n = 0;\n"
"        Value **items = arena_alloc(a, (size_t)cap * sizeof *items);\n"
"\n"
"        size_t start = 0;\n"
"        for (size_t i = 0; i + args[1]->len <= args[0]->len; ) {\n"
"            if (memcmp(args[0]->text + i, args[1]->text, args[1]->len) != 0) {\n"
"                i++;\n"
"                continue;\n"
"            }\n"
"            if (n == cap) {\n"
"                cap *= 2;\n"
"                Value **big = arena_alloc(a, (size_t)cap * sizeof *big);\n"
"                memcpy(big, items, (size_t)n * sizeof *big);\n"
"                items = big;\n"
"            }\n"
"            items[n++] = value_text(a, args[0]->text + start, i - start);\n"
"            i += args[1]->len;\n"
"            start = i;\n"
"        }\n"
"        if (n == cap) {\n"
"            Value **big = arena_alloc(a, (size_t)(cap + 1) * sizeof *big);\n"
"            memcpy(big, items, (size_t)n * sizeof *big);\n"
"            items = big;\n"
"        }\n"
"        items[n++] = value_text(a, args[0]->text + start, args[0]->len - start);\n"
"        return list_of(a, items, n);\n"
"    }\n"
"\n"
"    /* ---- lists ---- */\n"
"\n"
"    if (strcmp(f, \"size\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        switch (args[0]->kind) {\n"
"        case V_TEXT: return value_int(a, (long long)args[0]->len);\n"
"        case V_LIST:\n"
"        case V_NODE: return value_int(a, args[0]->n);\n"
"        default:\n"
"            return library_fail(e, x, \"'size' wants text, a list or a node, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"        }\n"
"    }\n"
"\n"
"    /* `sizes(list)` -- how big each element is, which is the companion to\n"
"     * `positions(list)`: that one answers where each thing is and this one how\n"
"     * big it is, and neither can be asked any other way. `each` applies a\n"
"     * *template* to a list, and a template can only write an element out.\n"
"     *\n"
"     * A table in a binary format is a column of lengths beside a column of\n"
"     * things, and the alternative to this was the same line of notation once\n"
"     * per node type that could be a row. */\n"
"    if (strcmp(f, \"sizes\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'sizes' wants a list, and this is %s\",\n"
"                                value_kind_name(args[0]));\n"
"\n"
"        Value **items = arena_alloc(a, (size_t)(args[0]->n ? args[0]->n : 1)\n"
"                                         * sizeof *items);\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            const Value *it = args[0]->items[i];\n"
"            switch (it->kind) {\n"
"            case V_TEXT: items[i] = value_int(a, (long long)it->len); break;\n"
"            case V_LIST:\n"
"            case V_NODE: items[i] = value_int(a, it->n);              break;\n"
"            default:\n"
"                return library_fail(e, x, \"'sizes' wants text, lists or nodes, \"\n"
"                                    \"and element %d is %s\", i + 1,\n"
"                                    value_kind_name(it));\n"
"            }\n"
"        }\n"
"        return list_of(a, items, args[0]->n);\n"
"    }\n"
"\n"
"    if (strcmp(f, \"at\") == 0) {\n"
"        if (!want(e, x, 2, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'at' wants a list, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"        if (args[1]->kind != V_INT)\n"
"            return library_fail(e, x, \"'at' wants an integer index, and this is %s\",\n"
"                        value_kind_name(args[1]));\n"
"\n"
"        long long i = args[1]->ival;         /* one-based, both ends included */\n"
"        if (i < 1 || i > args[0]->n)\n"
"            return library_fail(e, x, \"at(%lld) of a list of %d\", i, args[0]->n);\n"
"        return args[0]->items[i - 1];\n"
"    }\n"
"\n"
"    /* ---- flatten ----\n"
"     *\n"
"     * A declaration list is a list of declarations, each naming several\n"
"     * things: `var a, b : integer; c : real` is two nodes and three entries.\n"
"     * Turning that into one list is a fold, and there is no fold in a notation\n"
"     * with no conditional and no recursion -- `[...$vars.entries]` opens one\n"
"     * level and leaves a list of lists.\n"
"     *\n"
"     * It earns its place by the rule at the top of this file: a pass for a\n"
"     * real language needed it, and it could not be written in the notation.\n"
"     * One level only, because a deeper one would be guessing at what was\n"
"     * meant. */\n"
"    if (strcmp(f, \"flatten\") == 0) {\n"
"        if (!want(e, x, 1, args)) return NULL;\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'flatten' wants a list, and this is %s\",\n"
"                                value_kind_name(args[0]));\n"
"\n"
"        int total = 0;\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            const Value *item = args[0]->items[i];\n"
"            total += item->kind == V_LIST ? item->n : 1;\n"
"        }\n"
"\n"
"        Value **items = arena_alloc(a, (size_t)(total ? total : 1) * sizeof *items);\n"
"        int     n     = 0;\n"
"\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            Value *item = args[0]->items[i];\n"
"            if (item->kind == V_LIST)\n"
"                for (int k = 0; k < item->n; k++) items[n++] = item->items[k];\n"
"            else\n"
"                items[n++] = item;\n"
"        }\n"
"        return list_of(a, items, n);\n"
"    }\n"
"\n"
"    /* ---- each ----\n"
"     *\n"
"     * A template applied to every element of a list. There is no map in a\n"
"     * notation with no lambda, and every declaration list wants one: `var a, b\n"
"     * : Flags` is one node naming two things, and C wants `long a[30]` and\n"
"     * `long b[30]` written out.\n"
"     *\n"
"     * The template's `{}` is the element. It is built with `of` like any\n"
"     * other, so the parts that do not vary are already in it by the time this\n"
"     * is called:\n"
"     *\n"
"     *     each($names, \"{} {}{};\" of $type.pre, \"{}\", $type.post)\n"
"     */\n"
"    if (strcmp(f, \"each\") == 0) {\n"
"        bool two = x->nkids == 3;\n"
"        if (!two && !want(e, x, 2, args)) return NULL;\n"
"\n"
"        Value *template = two ? args[2] : args[1];\n"
"        Value *second   = two ? args[1] : NULL;\n"
"\n"
"        if (args[0]->kind != V_LIST || (two && second->kind != V_LIST))\n"
"            return library_fail(e, x, \"'each' wants a list\");\n"
"        if (template->kind != V_TEXT)\n"
"            return library_fail(e, x, \"'each' wants a template, and this is %s\",\n"
"                                value_kind_name(template));\n"
"\n"
"        /* Two lists **in step**, when two are given: one hole from each, in\n"
"         * order. Pairing a call's arguments with the parameters they are for\n"
"         * is what wanted it, and it is the same operation as one list with one\n"
"         * hole, so it is the same function.\n"
"         *\n"
"         * **It runs to the longer of the two.** Taking the first list's\n"
"         * length silently dropped everything the second had beyond it, which\n"
"         * is how `abs(i)` came out as `abs()`: the first list was what a call\n"
"         * puts before each argument, and a call to something the description\n"
"         * does not declare puts nothing before anything, so the first list was\n"
"         * empty and so was the answer. A list that runs out contributes\n"
"         * nothing; it does not end the walk. */\n"
"        int n = args[0]->n;\n"
"        if (two && second->n > n) n = second->n;\n"
"        Value **items = arena_alloc(a, (size_t)(n ? n : 1) * sizeof *items);\n"
"\n"
"        for (int i = 0; i < n; i++) {\n"
"            char  *pieces[2] = { \"\", \"\" };\n"
"            size_t lens[2]   = { 0, 0 };\n"
"\n"
"            if (i < args[0]->n\n"
"                && !value_format(a, args[0]->items[i], &pieces[0], &lens[0]))\n"
"                return library_fail(e, x, \"'each' cannot write a %s\",\n"
"                                    value_kind_name(args[0]->items[i]));\n"
"            if (two && i < second->n\n"
"                && !value_format(a, second->items[i], &pieces[1], &lens[1]))\n"
"                return library_fail(e, x, \"'each' cannot write a %s\",\n"
"                                    value_kind_name(second->items[i]));\n"
"\n"
"            size_t cap  = template->len + lens[0] + lens[1] + 1;\n"
"            char  *buf  = arena_alloc(a, cap + 1);\n"
"            size_t used = 0;\n"
"            int    hole = 0;\n"
"\n"
"            for (size_t k = 0; k < template->len; k++) {\n"
"                char c = template->text[k];\n"
"                if (c == '{' && k + 1 < template->len && template->text[k + 1] == '}') {\n"
"                    int which = hole < 2 ? hole : 1;\n"
"                    memcpy(buf + used, pieces[which], lens[which]);\n"
"                    used += lens[which];\n"
"                    hole++;\n"
"                    k++;\n"
"                    continue;\n"
"                }\n"
"                buf[used++] = c;\n"
"            }\n"
"            buf[used] = '\\0';\n"
"            items[i] = value_text(a, buf, used);\n"
"        }\n"
"        return list_of(a, items, n);\n"
"    }\n"
"\n"
"    if (strcmp(f, \"join\") == 0) {\n"
"        if (x->nkids != 1 && x->nkids != 2) {\n"
"            diag_error(&e->g->src, x->pos,\n"
"                       \"'join' takes a list, and optionally what to put between\");\n"
"            return NULL;\n"
"        }\n"
"        if (args[0]->kind != V_LIST)\n"
"            return library_fail(e, x, \"'join' wants a list, and this is %s\",\n"
"                        value_kind_name(args[0]));\n"
"\n"
"        const char *sep    = \"\";\n"
"        size_t      seplen = 0;\n"
"        if (x->nkids == 2) {\n"
"            if (args[1]->kind != V_TEXT)\n"
"                return library_fail(e, x, \"'join' wants text between, and this is %s\",\n"
"                            value_kind_name(args[1]));\n"
"            sep    = args[1]->text;\n"
"            seplen = args[1]->len;\n"
"        }\n"
"\n"
"        size_t total = 0;\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            if (value_failed(args[0]->items[i])) return args[0]->items[i];\n"
"\n"
"            char  *piece;\n"
"            size_t len;\n"
"            if (!value_format(a, args[0]->items[i], &piece, &len))\n"
"                return library_fail(e, x, \"'join' cannot write a %s\",\n"
"                            value_kind_name(args[0]->items[i]));\n"
"            total += len + (i ? seplen : 0);\n"
"        }\n"
"\n"
"        char  *buf  = arena_alloc(a, total + 1);\n"
"        size_t used = 0;\n"
"        for (int i = 0; i < args[0]->n; i++) {\n"
"            if (i) { memcpy(buf + used, sep, seplen); used += seplen; }\n"
"            char  *piece;\n"
"            size_t len;\n"
"            value_format(a, args[0]->items[i], &piece, &len);\n"
"            memcpy(buf + used, piece, len);\n"
"            used += len;\n"
"        }\n"
"        buf[used] = '\\0';\n"
"        return value_text(a, buf, used);\n"
"    }\n"
"\n"
"    return library_fail(e, x, \"there is no function called '%s'\", f);\n"
"}\n"
"/* lex.c -- characters to tokens, using the lexical half of the grammar.\n"
" *\n"
" * The rule is the one every lexer has: at each position, try every token rule\n"
" * and take the **longest** lex_match. Ties go to the rule declared first.\n"
" *\n"
" * That is deliberately not the ordered choice the syntactic half uses, and the\n"
" * difference is the reason `\"<\" | \"<=\"` is a question there and not here. A\n"
" * scanner that took the first lex_match would have to be told, by ordering, that\n"
" * `<=` is longer than `<`. One that takes the longest already knows.\n"
" *\n"
" * Within a single rule, though, the alternatives *are* ordered -- `a | b`\n"
" * tries `a` first -- so a rule that gathers punctuation still has to put the\n"
" * two-character symbols before the one-character ones. check.c warns when it\n"
" * does not.\n"
" */\n"
"\n"
"#include <string.h>\n"
"\n"
"typedef struct {\n"
"    const Grammar *g;\n"
"    const Source  *src;\n"
"} Lex;\n"
"\n"
"static long lex_match(Lex *l, const GNode *n, long pos);\n"
"\n"
"static char lex_lower(char c)\n"
"{\n"
"    return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;\n"
"}\n"
"\n"
"static bool lex_same(const Lex *l, const char *a, const char *b, size_t len)\n"
"{\n"
"    if (!l->g->ignorecase) return memcmp(a, b, len) == 0;\n"
"    for (size_t i = 0; i < len; i++)\n"
"        if (lex_lower(a[i]) != lex_lower(b[i])) return false;\n"
"    return true;\n"
"}\n"
"\n"
"/* Answers where the lex_match ended, or -1. */\n"
"extern Work phx_work;\n"
"\n"
"static long lex_match(Lex *l, const GNode *n, long pos)\n"
"{\n"
"    const char *s    = l->src->text;\n"
"    long        size = (long)l->src->size;\n"
"\n"
"    phx_work.lex_steps++;\n"
"\n"
"    switch (n->kind) {\n"
"    case G_LIT:\n"
"        if (pos + n->len > size) return -1;\n"
"        return lex_same(l, s + pos, n->text, (size_t)n->len) ? pos + n->len : -1;\n"
"\n"
"    case G_RANGE: {\n"
"        if (pos >= size) return -1;\n"
"        char c  = s[pos];\n"
"        char lo = n->text[0], hi = n->upto[0];\n"
"        if (l->g->ignorecase) { c = lex_lower(c); lo = lex_lower(lo); hi = lex_lower(hi); }\n"
"        return (c >= lo && c <= hi) ? pos + 1 : -1;\n"
"    }\n"
"\n"
"    case G_NAME:\n"
"        return lex_match(l, l->g->rules[n->ref].body, pos);\n"
"\n"
"    case G_SEQ:\n"
"        for (int i = 0; i < n->nkids; i++) {\n"
"            pos = lex_match(l, n->kids[i], pos);\n"
"            if (pos < 0) return -1;\n"
"        }\n"
"        return pos;\n"
"\n"
"    case G_ALT:\n"
"        for (int i = 0; i < n->nkids; i++) {\n"
"            long got = lex_match(l, n->kids[i], pos);\n"
"            if (got >= 0) return got;\n"
"        }\n"
"        return -1;\n"
"\n"
"    case G_OPT: {\n"
"        long got = lex_match(l, n->kids[0], pos);\n"
"        return got >= 0 ? got : pos;\n"
"    }\n"
"\n"
"    case G_REP:\n"
"        for (;;) {\n"
"            long got = lex_match(l, n->kids[0], pos);\n"
"            if (got < 0) return pos;\n"
"            if (got == pos) return pos;      /* an empty body would spin here */\n"
"            pos = got;\n"
"        }\n"
"\n"
"    case G_NOT:\n"
"        /* One character, provided the inner factor does not lex_match here. It is\n"
"         * PEG's negative lookahead with a character taken after it, which is\n"
"         * the only form anybody writes: `\"{\" { ! \"}\" } \"}\"` is a comment. */\n"
"        if (pos >= size) return -1;\n"
"        return lex_match(l, n->kids[0], pos) >= 0 ? -1 : pos + 1;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"static void push(Arena *a, Tokens *t, Token tok)\n"
"{\n"
"    if (t->n == t->cap) {\n"
"        int    cap = t->cap ? t->cap * 2 : 512;\n"
"        Token *big = arena_alloc(a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, t->items, (size_t)t->n * sizeof *big);\n"
"        t->items = big;\n"
"        t->cap   = cap;\n"
"    }\n"
"    t->items[t->n++] = tok;\n"
"}\n"
"\n"
"/* How many unmatched characters are worth reporting before the file is\n"
" * plainly not the language it was said to be. */\n"
"#define MAX_BAD 20\n"
"\n"
"bool lex_run(Arena *a, const Grammar *g, const Source *src, Tokens *out)\n"
"{\n"
"    Lex  l   = { .g = g, .src = src };\n"
"    long pos = 0;\n"
"    int  bad = 0;\n"
"\n"
"    memset(out, 0, sizeof *out);\n"
"\n"
"    while (pos < (long)src->size) {\n"
"        long best     = -1;\n"
"        int  best_rule = -1;\n"
"\n"
"        for (int i = 0; i < g->nrules; i++) {\n"
"            const Rule *r = &g->rules[i];\n"
"            if (!r->lexical || r->fragment || !r->body) continue;\n"
"\n"
"            long got = lex_match(&l, r->body, pos);\n"
"\n"
"            /* A zero-length lex_match is not a token; it would leave the scanner\n"
"             * exactly where it was, forever. */\n"
"            if (got > pos && got > best) { best = got; best_rule = i; }\n"
"        }\n"
"\n"
"        if (best_rule < 0) {\n"
"            /* Take the character and carry on, rather than stopping. A scan\n"
"             * that halts at the first character it cannot read tells you the\n"
"             * least about the file you know the least about -- two stray\n"
"             * characters on two lines should produce two messages, not one\n"
"             * message and a mystery. */\n"
"            if (++bad <= MAX_BAD)\n"
"                diag_error(src, (size_t)pos, \"nothing here matches any token rule\");\n"
"            if (bad == MAX_BAD + 1)\n"
"                diag_note(\"%d unreadable characters so far; not listing the rest\",\n"
"                          bad);\n"
"            pos++;\n"
"            continue;\n"
"        }\n"
"\n"
"        if (!g->rules[best_rule].skip)\n"
"            push(a, out, (Token){ .kind = best_rule,\n"
"                                  .text = src->text + pos,\n"
"                                  .len  = (size_t)(best - pos),\n"
"                                  .pos  = (size_t)pos });\n"
"        pos = best;\n"
"    }\n"
"    return bad == 0;\n"
"}\n"
"\n"
"bool lex_produces(const Grammar *g, const char *text, size_t len)\n"
"{\n"
"    Source one = { .path = \"\", .text = (char *)text, .size = len };\n"
"    Lex    l   = { .g = g, .src = &one };\n"
"\n"
"    for (int i = 0; i < g->nrules; i++) {\n"
"        const Rule *r = &g->rules[i];\n"
"        if (!r->lexical || r->fragment || r->skip || !r->body) continue;\n"
"\n"
"        /* The whole of it, and as one token. A rule matching just the `:` of\n"
"         * a `:=` has not produced the literal the syntactic half asked for. */\n"
"        if (lex_match(&l, r->body, 0) == (long)len) return true;\n"
"    }\n"
"    return false;\n"
"}\n"
"\n"
"void tokens_dump(FILE *out, const Grammar *g, const Source *src, const Tokens *t)\n"
"{\n"
"    for (int i = 0; i < t->n; i++) {\n"
"        const Token *tok = &t->items[i];\n"
"        int line, col;\n"
"        source_position(src, tok->pos, &line, &col);\n"
"        fprintf(out, \"%4d:%-3d  %-18s %.*s\\n\",\n"
"                line, col, g->rules[tok->kind].name, (int)tok->len, tok->text);\n"
"    }\n"
"}\n"
"/* parse.c -- tokens to a tree, using the syntactic half of the grammar.\n"
" *\n"
" * **Ordered choice with local backtracking** -- a PEG, not a general parser.\n"
" * `a | b` tries `a`, and tries `b` only if `a` failed. If `a` succeeds and the\n"
" * rule around it fails later, the choice is *not* revisited.\n"
" *\n"
" * That is a real restriction, and it is written here rather than buried,\n"
" * because the failure it produces is a syntax error on a file that is correct.\n"
" * It costs nothing on an LL(1) grammar, which is what Wirth's Pascal is and\n"
" * what almost every published grammar is. It costs something on a grammar with\n"
" * an alternative that is a proper prefix of a later one.\n"
" *\n"
" * When the parse_match fails, the position it got *furthest* is the one worth\n"
" * reporting -- not the position it stopped at. A PEG that fails at the top has\n"
" * usually backtracked a long way from where the real mistake is, and the\n"
" * furthest token it ever reached is very nearly always the place a person\n"
" * would point at.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * What a parse_match produces\n"
" *\n"
" * Matching appends **values** to a list belonging to the enclosing sequence.\n"
" * A literal or a token appends one. A rule appends whatever its body answered.\n"
" * A sequence carrying an action gathers its factors, evaluates the action, and\n"
" * appends the single value that came out.\n"
" *\n"
" * A rule's answer follows one rule with no exceptions: **a body that produced\n"
" * one value answers that value; a body that produced any other number answers\n"
" * a node named after the rule, holding them.** So a chain of rules that each\n"
" * pass one thing along collapses to the thing, and the interior nodes a\n"
" * hand-written tree-builder exists to strip are never built at all.\n"
" */\n"
"\n"
"#include <string.h>\n"
"\n"
"extern Work phx_work;\n"
"\n"
"/* A growable list of values -- one per sequence being matched. */\n"
"typedef struct {\n"
"    Value **items;\n"
"    int     n;\n"
"    int     cap;\n"
"} Slots;\n"
"\n"
"typedef struct {\n"
"    Arena         *a;\n"
"    const Grammar *g;\n"
"    const Source  *src;\n"
"    const Tokens  *t;\n"
"\n"
"    long           furthest;      /* the highest token index ever reached   */\n"
"    int            depth;         /* how deep the matcher is, right now      */\n"
"    const char   **wanted;        /* what was being asked for there         */\n"
"    int            nwanted;\n"
"    int            capwanted;\n"
"} Parse;\n"
"\n"
"static long parse_match(Parse *p, const GNode *n, long at, Slots *out);\n"
"static long parse_body(Parse *p, const GNode *n, long at, Slots *out);\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"static char parse_lower(char c)\n"
"{\n"
"    return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;\n"
"}\n"
"\n"
"static bool parse_same(const Parse *p, const char *a, size_t alen,\n"
"                 const char *b, size_t blen)\n"
"{\n"
"    if (alen != blen) return false;\n"
"    if (!p->g->ignorecase) return memcmp(a, b, alen) == 0;\n"
"    for (size_t i = 0; i < alen; i++)\n"
"        if (parse_lower(a[i]) != parse_lower(b[i])) return false;\n"
"    return true;\n"
"}\n"
"\n"
"static bool reserved(const Parse *p, const char *text, size_t len)\n"
"{\n"
"    for (int i = 0; i < p->g->nreserved; i++)\n"
"        if (parse_same(p, p->g->reserved[i], strlen(p->g->reserved[i]), text, len))\n"
"            return true;\n"
"    return false;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Where it got furthest, and what it wanted there */\n"
"\n"
"static void note_want(Parse *p, long at, const char *what)\n"
"{\n"
"    if (at < p->furthest) return;\n"
"\n"
"    if (at > p->furthest) {\n"
"        p->furthest = at;\n"
"        p->nwanted  = 0;\n"
"    }\n"
"    for (int i = 0; i < p->nwanted; i++)\n"
"        if (strcmp(p->wanted[i], what) == 0) return;\n"
"\n"
"    if (p->nwanted == p->capwanted) {\n"
"        int          cap = p->capwanted ? p->capwanted * 2 : 16;\n"
"        const char **big = arena_alloc(p->a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, p->wanted, (size_t)p->nwanted * sizeof *big);\n"
"        p->wanted    = big;\n"
"        p->capwanted = cap;\n"
"    }\n"
"    p->wanted[p->nwanted++] = what;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Values */\n"
"\n"
"static Value *value_new(Parse *p, VKind kind, size_t pos)\n"
"{\n"
"    phx_work.nodes++;\n"
"    Value *v = arena_alloc(p->a, sizeof *v);\n"
"    v->kind  = kind;\n"
"    v->pos   = pos;\n"
"    return v;\n"
"}\n"
"\n"
"static Value *token_value(Parse *p, const Token *tok)\n"
"{\n"
"    Value *v  = value_new(p, V_TEXT, tok->pos);\n"
"    v->text   = tok->text;\n"
"    v->len    = tok->len;\n"
"    v->endpos = tok->pos + (tok->len ? tok->len - 1 : 0);\n"
"    return v;\n"
"}\n"
"\n"
"static void slots_add(Parse *p, Slots *s, Value *v)\n"
"{\n"
"    if (s->n == s->cap) {\n"
"        int     cap = s->cap ? s->cap * 2 : 8;\n"
"        Value **big = arena_alloc(p->a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, s->items, (size_t)s->n * sizeof *big);\n"
"        s->items = big;\n"
"        s->cap   = cap;\n"
"    }\n"
"    s->items[s->n++] = v;\n"
"}\n"
"\n"
"/* Several values become one: a lone value passes through, anything else is\n"
" * gathered into a list. This is the rule the header states, and the only place\n"
" * it is decided. */\n"
"static Value *one_of(Parse *p, Slots *s, size_t pos)\n"
"{\n"
"    if (s->n == 1) return s->items[0];\n"
"\n"
"    Value *v = value_new(p, V_LIST, pos);\n"
"    v->items = s->items;\n"
"    v->n     = s->n;\n"
"    return v;\n"
"}\n"
"\n"
"/* ...except where the grammar already says the count is not fixed.\n"
" *\n"
" * `{ statement }` matched once is one value and matched twice is two, and\n"
" * which of those happened is a property of the file being compiled rather\n"
" * than of the grammar. Collapsing the single case would make `$body` a node\n"
" * in a one-statement block and a list in every other, so a `.phx` could not\n"
" * be written that handled both -- and would only find out on the first\n"
" * one-statement block anybody wrote.\n"
" *\n"
" * So a repetition and an option are lists always, of whatever length they\n"
" * turned out to be, and everything else collapses as above. The rule is\n"
" * decidable from the grammar, which is the property that matters. */\n"
"static bool varies(const GNode *factor)\n"
"{\n"
"    return factor->kind == G_REP || factor->kind == G_OPT;\n"
"}\n"
"\n"
"static Value *slot_value(Parse *p, const GNode *factor, Slots *s, size_t pos)\n"
"{\n"
"    if (!varies(factor)) return one_of(p, s, pos);\n"
"\n"
"    Value *v = value_new(p, V_LIST, pos);\n"
"    v->items = s->items;\n"
"    v->n     = s->n;\n"
"    return v;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Evaluating an action\n"
" *\n"
" * The expression itself is evaluated by eval.c, which is the parse_same code a\n"
" * stage-2 pass clause runs. All this half provides is what `$2`, `$name` and\n"
" * `$$` mean *here*: the factors of the sequence being built, and the value the\n"
" * enclosing sequence built last.\n"
" */\n"
"\n"
"typedef struct {\n"
"    Parse       *p;\n"
"    const GNode *seq;      /* the sequence being built, for its labels    */\n"
"    Slots       *slots;\n"
"    Value       *acc;\n"
"} Build;\n"
"\n"
"static Value *build_ref(Eval *e, const Expr *x)\n"
"{\n"
"    Build *b = e->data;\n"
"\n"
"    if (x->kind == X_ACC) {\n"
"        if (!b->acc) {\n"
"            diag_error(&e->g->src, x->pos,\n"
"                       \"$$ is nothing here -- there is no value before this one\");\n"
"            return NULL;\n"
"        }\n"
"        return b->acc;\n"
"    }\n"
"\n"
"    if (x->kind == X_DOT) {\n"
"        diag_error(&e->g->src, x->pos,\n"
"                   \"'.%s' reads an attribute, and a production has none -- \"\n"
"                   \"attributes belong to a %%pass\", x->name);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    int index = x->index;\n"
"\n"
"    if (x->name) {                              /* by label */\n"
"        index = 0;\n"
"        for (int i = 0; i < b->seq->nkids; i++)\n"
"            if (b->seq->kids[i]->label\n"
"                && strcmp(b->seq->kids[i]->label, x->name) == 0) {\n"
"                index = i + 1;\n"
"                break;\n"
"            }\n"
"        if (!index) {\n"
"            diag_error(&e->g->src, x->pos, \"no factor here is named '%s'\", x->name);\n"
"            return NULL;\n"
"        }\n"
"    }\n"
"    if (index > b->slots->n) {\n"
"        diag_error(&e->g->src, x->pos,\n"
"                   \"$%d, but this alternative has %d factor%s\",\n"
"                   index, b->slots->n, b->slots->n == 1 ? \"\" : \"s\");\n"
"        return NULL;\n"
"    }\n"
"    return b->slots->items[index - 1];\n"
"}\n"
"\n"
"/* Whether an action mentions `$$`, and so folds rather than appends. */\n"
"static bool folds(const Expr *x)\n"
"{\n"
"    if (!x) return false;\n"
"    if (x->kind == X_ACC) return true;\n"
"    for (int i = 0; i < x->nkids; i++)\n"
"        if (folds(x->kids[i])) return true;\n"
"    return false;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"/* A sequence carrying an action: each factor gets a slot of its own, so that\n"
" * `$2` means the second factor and not the second value -- a `{ }` producing\n"
" * three things still occupies one position. */\n"
"static long match_action_seq(Parse *p, const GNode *n, long at, Slots *out)\n"
"{\n"
"    Slots *slots = arena_alloc(p->a, (size_t)(n->nkids ? n->nkids : 1) * sizeof *slots);\n"
"    memset(slots, 0, (size_t)(n->nkids ? n->nkids : 1) * sizeof *slots);\n"
"\n"
"    Slots gathered = { 0 };\n"
"    long   from = at;\n"
"    size_t pos  = at < p->t->n ? p->t->items[at].pos : p->src->size;\n"
"\n"
"    for (int i = 0; i < n->nkids; i++) {\n"
"        at = parse_match(p, n->kids[i], at, &slots[i]);\n"
"        if (at < 0) return -1;\n"
"        slots_add(p, &gathered, slot_value(p, n->kids[i], &slots[i], pos));\n"
"    }\n"
"\n"
"    /* The last byte of the last token this sequence consumed. A sequence that\n"
"     * consumed none -- an empty alternative -- ends where it began, rather\n"
"     * than at the token before it. */\n"
"    size_t endpos = pos;\n"
"    if (at > from) {\n"
"        const Token *last = &p->t->items[at - 1];\n"
"        endpos = last->pos + (last->len ? last->len - 1 : 0);\n"
"    }\n"
"\n"
"    Build b = { .p = p, .seq = n, .slots = &gathered, .acc = NULL };\n"
"    Eval  e = { .a = p->a, .g = p->g, .ref = build_ref, .data = &b,\n"
"                .pos = pos, .endpos = endpos };\n"
"\n"
"    /* `$$` is the value the enclosing sequence built last, and the result\n"
"     * takes its place rather than following it. That is the whole of a left\n"
"     * fold, and it is why the flat repetition a grammar writes for a binary\n"
"     * operator comes out as the tree it means. */\n"
"    bool fold = folds(n->action);\n"
"    if (fold) {\n"
"        if (out->n == 0) {\n"
"            diag_error(&p->g->src, n->action->pos,\n"
"                       \"$$ is nothing here -- there is no value before this one\");\n"
"            return -1;\n"
"        }\n"
"        b.acc = out->items[out->n - 1];\n"
"    }\n"
"\n"
"    Value *built = eval_expr(&e, n->action);\n"
"    if (!built) return -1;\n"
"\n"
"    if (fold) out->items[out->n - 1] = built;\n"
"    else      slots_add(p, out, built);\n"
"\n"
"    return at;\n"
"}\n"
"\n"
"/* How deep the matcher may go before it says so.\n"
" *\n"
" * Matching is recursive descent, so the C stack is proportional to how deeply\n"
" * the *input* nests -- and input is not something a compiler gets to trust.\n"
" * Measuring found the real limit at about 3,400 nested parentheses and a\n"
" * SIGSEGV, which is never an answer: a crash tells the person nothing and\n"
" * cannot be caught.\n"
" *\n"
" * Pascal's grammar spends about ten frames a parenthesis, and no program\n"
" * anybody writes nests past a few dozen -- `gcd.pas` reaches 60. This is set\n"
" * an order of magnitude above anything real and an order below where the\n"
" * stack actually goes. */\n"
"#define MAX_DEPTH 10000\n"
"\n"
"static long parse_match(Parse *p, const GNode *n, long at, Slots *out)\n"
"{\n"
"    const Token *toks = p->t->items;\n"
"    long         end  = p->t->n;\n"
"\n"
"    phx_work.parse_steps++;\n"
"\n"
"    if (++p->depth > MAX_DEPTH) {\n"
"        p->depth--;\n"
"        if (!diag_failed())\n"
"            diag_error(p->src, at < end ? toks[at].pos : p->src->size,\n"
"                       \"nested too deeply here -- more than %d levels, which is \"\n"
"                       \"past anything a person writes\", MAX_DEPTH);\n"
"        return -1;\n"
"    }\n"
"    if (p->depth > phx_work.depth) phx_work.depth = p->depth;\n"
"\n"
"    long answer = parse_body(p, n, at, out);\n"
"    p->depth--;\n"
"    return answer;\n"
"}\n"
"\n"
"static long parse_body(Parse *p, const GNode *n, long at, Slots *out)\n"
"{\n"
"    const Token *toks = p->t->items;\n"
"    long         end  = p->t->n;\n"
"\n"
"    switch (n->kind) {\n"
"    case G_LIT: {\n"
"        if (at >= end) { note_want(p, at, n->text); return -1; }\n"
"        if (!parse_same(p, toks[at].text, toks[at].len, n->text, (size_t)n->len)) {\n"
"            note_want(p, at, n->text);\n"
"            return -1;\n"
"        }\n"
"        slots_add(p, out, token_value(p, &toks[at]));\n"
"        return at + 1;\n"
"    }\n"
"\n"
"    case G_NAME: {\n"
"        const Rule *r = &p->g->rules[n->ref];\n"
"\n"
"        /* A name that means a lexical rule is a token kind: any token the\n"
"         * scanner made with that rule will do. */\n"
"        if (r->lexical) {\n"
"            if (at >= end || toks[at].kind != n->ref) {\n"
"                note_want(p, at, r->name);\n"
"                return -1;\n"
"            }\n"
"            /* ...except a reserved word. `begin` is spelled like an\n"
"             * identifier and the scanner cannot tell them apart; the\n"
"             * syntactic half is what knows, because it names `begin`\n"
"             * somewhere. */\n"
"            if (reserved(p, toks[at].text, toks[at].len)) {\n"
"                note_want(p, at, r->name);\n"
"                return -1;\n"
"            }\n"
"            slots_add(p, out, token_value(p, &toks[at]));\n"
"            return at + 1;\n"
"        }\n"
"\n"
"        Slots  inner = { 0 };\n"
"        size_t pos   = at < end ? toks[at].pos : p->src->size;\n"
"\n"
"        long got = parse_match(p, r->body, at, &inner);\n"
"        if (got < 0) return -1;\n"
"\n"
"        Value *v = inner.n == 1 ? inner.items[0] : NULL;\n"
"        if (!v) {\n"
"            v        = value_new(p, V_NODE, pos);\n"
"            v->type  = r->name;\n"
"            v->items = inner.items;\n"
"            v->n     = inner.n;\n"
"        }\n"
"        slots_add(p, out, v);\n"
"        return got;\n"
"    }\n"
"\n"
"    case G_SEQ: {\n"
"        if (n->action) return match_action_seq(p, n, at, out);\n"
"\n"
"        int keep = out->n;\n"
"        for (int i = 0; i < n->nkids; i++) {\n"
"            at = parse_match(p, n->kids[i], at, out);\n"
"            if (at < 0) { out->n = keep; return -1; }\n"
"        }\n"
"        return at;\n"
"    }\n"
"\n"
"    case G_ALT:\n"
"        for (int i = 0; i < n->nkids; i++) {\n"
"            int  keep = out->n;\n"
"            long got  = parse_match(p, n->kids[i], at, out);\n"
"            if (got >= 0) return got;\n"
"            out->n = keep;\n"
"        }\n"
"        return -1;\n"
"\n"
"    case G_OPT: {\n"
"        int  keep = out->n;\n"
"        long got  = parse_match(p, n->kids[0], at, out);\n"
"        if (got >= 0) return got;\n"
"        out->n = keep;\n"
"        return at;\n"
"    }\n"
"\n"
"    case G_REP:\n"
"        for (;;) {\n"
"            int  keep = out->n;\n"
"            long got  = parse_match(p, n->kids[0], at, out);\n"
"            if (got < 0)  { out->n = keep; return at; }\n"
"            if (got == at) return at;              /* an empty body */\n"
"            at = got;\n"
"        }\n"
"\n"
"    case G_RANGE:\n"
"    case G_NOT:\n"
"        /* check.c refuses these in a syntactic rule, so reaching one here is\n"
"         * a defect in Phoenix rather than in the grammar. */\n"
"        return -1;\n"
"    }\n"
"    return -1;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"static void report_failure(Parse *p)\n"
"{\n"
"    const Tokens *t = p->t;\n"
"    size_t where = p->furthest < t->n ? t->items[p->furthest].pos : p->src->size;\n"
"\n"
"    char   buf[512];\n"
"    size_t used = 0;\n"
"    buf[0] = '\\0';\n"
"\n"
"    for (int i = 0; i < p->nwanted && used < sizeof buf - 8; i++) {\n"
"        const char *sep = i == 0 ? \"\" : (i == p->nwanted - 1 ? \" or \" : \", \");\n"
"        int wrote = snprintf(buf + used, sizeof buf - used, \"%s%s\", sep, p->wanted[i]);\n"
"        if (wrote < 0) break;\n"
"        used += (size_t)wrote;\n"
"    }\n"
"\n"
"    if (p->furthest < t->n) {\n"
"        const Token *tok = &t->items[p->furthest];\n"
"        diag_error(p->src, where, \"expected %s, and found \\\"%.*s\\\"\",\n"
"                   p->nwanted ? buf : \"something else\", (int)tok->len, tok->text);\n"
"    } else {\n"
"        diag_error(p->src, where, \"expected %s, and the file ended\",\n"
"                   p->nwanted ? buf : \"more\");\n"
"    }\n"
"}\n"
"\n"
"Value *parse_run(Arena *a, const Grammar *g, const Source *src, const Tokens *t)\n"
"{\n"
"    Parse p = { .a = a, .g = g, .src = src, .t = t, .furthest = 0 };\n"
"\n"
"    const Rule *start = &g->rules[g->start];\n"
"    Slots       out   = { 0 };\n"
"\n"
"    long got = parse_match(&p, start->body, 0, &out);\n"
"    if (got < 0)      { report_failure(&p); return NULL; }\n"
"    if (diag_failed()) return NULL;          /* an action went wrong */\n"
"\n"
"    if (got < t->n) {\n"
"        /* The goal matched, and there is more file. That is a syntax error at\n"
"         * the first thing left over, not a success. */\n"
"        p.furthest = got;\n"
"        report_failure(&p);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    if (out.n == 1) return out.items[0];\n"
"\n"
"    Value *root = value_new(&p, V_NODE, 0);\n"
"    root->type  = start->name;\n"
"    root->items = out.items;\n"
"    root->n     = out.n;\n"
"    return root;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Printing a tree */\n"
"\n"
"static void dump(FILE *out, Arena *a, const Value *v, const char *prefix,\n"
"                 bool last, const char *field, bool root)\n"
"{\n"
"    char here[512];\n"
"\n"
"    if (root) {\n"
"        here[0] = '\\0';\n"
"    } else {\n"
"        fprintf(out, \"%s%s\", prefix, last ? \"`- \" : \"|- \");\n"
"        if (field) fprintf(out, \"%s: \", field);\n"
"        snprintf(here, sizeof here, \"%s%s\", prefix, last ? \"   \" : \"|  \");\n"
"    }\n"
"\n"
"    switch (v->kind) {\n"
"    case V_TEXT:\n"
"        fprintf(out, \"\\\"%.*s\\\"\\n\", (int)v->len, v->text);\n"
"        return;\n"
"\n"
"    case V_ERROR:\n"
"        fputs(\"<failed>\\n\", out);\n"
"        return;\n"
"\n"
"    case V_INT: case V_FLOAT: case V_BOOL: case V_NIL: {\n"
"        char  *text;\n"
"        size_t len;\n"
"        if (v->kind == V_NIL)                fputs(\"nil\\n\", out);\n"
"        else if (value_format(a, v, &text, &len)) fprintf(out, \"%.*s\\n\", (int)len, text);\n"
"        else                                 fputs(\"?\\n\", out);\n"
"        return;\n"
"    }\n"
"\n"
"    case V_NODE:\n"
"        fprintf(out, \"%s\\n\", v->type);\n"
"        break;\n"
"    case V_LIST:\n"
"        fprintf(out, \"[%d]\\n\", v->n);\n"
"        break;\n"
"    }\n"
"\n"
"    for (int i = 0; i < v->n; i++)\n"
"        dump(out, a, v->items[i], here, i == v->n - 1,\n"
"             v->fields ? v->fields[i] : NULL, false);\n"
"}\n"
"\n"
"void tree_dump(FILE *out, const Value *root)\n"
"{\n"
"    Arena *a = arena_new();\n"
"    dump(out, a, root, \"\", true, NULL, true);\n"
"    arena_free(a);\n"
"}\n"
"/* include.c -- a target language's own includes.\n"
" *\n"
" * `%import` splices one description into another; this is the same thing one\n"
" * level down, for the language being described.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * Why it is not a pass\n"
" *\n"
" * Every other thing a description says about meaning is a clause, and the\n"
" * first question here was whether this could be one too. It cannot, and the\n"
" * reason is the definition of a pass: **a walk over one tree that has already\n"
" * been read.** An include is a second file, which has to be read before there\n"
" * is a tree to walk. No clause can reach it, however it is written.\n"
" *\n"
" * So this runs once, between the parser and the first pass, and everything\n"
" * after it sees a single tree that never mentions a second file. A backend\n"
" * needs no clause for an include and cannot encounter one.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * What the description has to say\n"
" *\n"
" *     %include Include path .\n"
" *\n"
" * The node that stands for an include, and the field that holds the name of\n"
" * the file. That is the whole of the notation, and nothing in this file knows\n"
" * anything about any particular language.\n"
" *\n"
" * The field's text is used **exactly as it stands**, which is a decision worth\n"
" * naming: a token arrives spelled the way the file spelled it, quotes and all,\n"
" * and stripping them here would mean guessing how the target writes a string.\n"
" * The description already has the means to say it -- Solveig's include builds\n"
" * `Include(path: slice($p, 2, size($p) - 1))` -- so the guess is not needed.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * What a splice is\n"
" *\n"
" * The include node is replaced, **in the list that holds it**, by the items\n"
" * the included file's root holds. A file's root is a list, or a node with one\n"
" * field which is a list -- Solveig's `Program(body: [...])` -- and anything\n"
" * else is refused, because there is no answer to which half of a root with two\n"
" * parts a statement position wants.\n"
" *\n"
" * An include that is not in a list is refused for the same reason from the\n"
" * other side: a file has nowhere to go where one value is expected.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * Three new ways to fail, which is what made this worth being careful about\n"
" *\n"
" * A reader that reads one file can fail in one way. A reader that follows\n"
" * files fails in three more, and each gets a message at the position of the\n"
" * include that caused it:\n"
" *\n"
" *   - **the file is not there.** The message says where it was looked for,\n"
" *     because \"beside the includer, then the search path\" is exactly the rule\n"
" *     nobody can reconstruct from a bare failure.\n"
" *   - **relative to which file?** Beside the file the include is *written in*,\n"
" *     never the one the command line named, so a program keeps working when it\n"
" *     is moved. That is C's rule for `#include \"...\"` and it is C's reason.\n"
" *   - **a cycle.** Not detected, because there is nothing to detect: a file is\n"
" *     read once however many ways it is reached, so a file that comes round to\n"
" *     itself finds itself already read and contributes nothing. Two files that\n"
" *     include each other terminate for the same reason `%import` does.\n"
" */\n"
"\n"
"#include <string.h>\n"
"\n"
"typedef struct {\n"
"    Arena             *a;\n"
"    const Grammar     *g;\n"
"    Source            *src;       /* the joined text, grown as files arrive  */\n"
"    SourceMap         *map;\n"
"    const IncludePath *look;\n"
"\n"
"    char             **done;      /* the files already read, by identity     */\n"
"    int                ndone;\n"
"    int                capdone;\n"
"\n"
"    int                depth;     /* only to keep a runaway from the stack   */\n"
"    bool               ok;\n"
"} Includer;\n"
"\n"
"/* A file that includes a file that includes a file. Nothing sensible is this\n"
" * deep, and a reader that recurses wants a floor under it whatever the\n"
" * once-only rule promises. */\n"
"#define INCLUDE_DEPTH 64\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Paths */\n"
"\n"
"void include_path_add(Arena *a, IncludePath *look, const char *dir)\n"
"{\n"
"    if (look->n == look->cap) {\n"
"        int          cap = look->cap ? look->cap * 2 : 4;\n"
"        const char **big = arena_alloc(a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, look->dirs, (size_t)look->n * sizeof *big);\n"
"        look->dirs = big;\n"
"        look->cap  = cap;\n"
"    }\n"
"    look->dirs[look->n++] = dir;\n"
"}\n"
"\n"
"/* `dir/of/includer` + `named` */\n"
"static char *path_beside(Arena *a, const char *beside, const char *name)\n"
"{\n"
"    const char *slash = strrchr(beside, '/');\n"
"    if (!slash) return arena_strndup(a, name, strlen(name));\n"
"\n"
"    size_t dir = (size_t)(slash - beside) + 1;\n"
"    size_t n   = strlen(name);\n"
"    char  *out = arena_alloc(a, dir + n + 1);\n"
"\n"
"    memcpy(out, beside, dir);\n"
"    memcpy(out + dir, name, n);\n"
"    out[dir + n] = '\\0';\n"
"    return out;\n"
"}\n"
"\n"
"/* `dir` + `/` + `named`, for a search path entry, which is a directory rather\n"
" * than a file and so has no name to strip off the end. */\n"
"static char *path_under(Arena *a, const char *dir, const char *name)\n"
"{\n"
"    size_t d = strlen(dir);\n"
"    size_t n = strlen(name);\n"
"    bool   sep = d && dir[d - 1] != '/';\n"
"    char  *out = arena_alloc(a, d + (sep ? 1 : 0) + n + 1);\n"
"\n"
"    memcpy(out, dir, d);\n"
"    if (sep) out[d++] = '/';\n"
"    memcpy(out + d, name, n);\n"
"    out[d + n] = '\\0';\n"
"    return out;\n"
"}\n"
"\n"
"/* Two spellings of one file, told apart.\n"
" *\n"
" * `a/./b`, `a//b` and `a/x/../b` are `a/b`, so a file reached beside its\n"
" * includer and again from the search path is recognised as the one file it is.\n"
" *\n"
" * **This is spelling and not identity**, and the difference is a symbolic link\n"
" * or two roots onto the same directory, which this will read twice. `realpath`\n"
" * is the answer to that and is POSIX; a generated compiler is meant to build\n"
" * with `cc file.c` and nothing else, and this file is part of one. The cost of\n"
" * being wrong is a file compiled twice rather than once, which is visible\n"
" * rather than quiet -- it runs twice -- so the trade is the safe way round.\n"
" */\n"
"static char *identity_of(Arena *a, const char *path)\n"
"{\n"
"    size_t n   = strlen(path);\n"
"    char  *out = arena_alloc(a, n + 2);\n"
"    size_t w   = 0;\n"
"\n"
"    /* Segment by segment, keeping a stack of where each kept one began so\n"
"     * that `..` can pop the last. */\n"
"    size_t *marks = arena_alloc(a, (n + 2) * sizeof *marks);\n"
"    int     nmark = 0;\n"
"\n"
"    size_t i = 0;\n"
"    if (path[0] == '/') out[w++] = '/', i = 1;\n"
"\n"
"    while (i < n) {\n"
"        size_t start = i;\n"
"        while (i < n && path[i] != '/') i++;\n"
"        size_t len = i - start;\n"
"        while (i < n && path[i] == '/') i++;\n"
"\n"
"        if (len == 0) continue;\n"
"        if (len == 1 && path[start] == '.') continue;\n"
"\n"
"        bool up = len == 2 && path[start] == '.' && path[start + 1] == '.';\n"
"        if (up && nmark) {\n"
"            w = marks[--nmark];          /* the segment before it, undone */\n"
"            continue;\n"
"        }\n"
"\n"
"        /* A `..` that had nothing to undo stays, and is *not* marked -- or the\n"
"         * next one would undo it, and `../../a` would fold to `a`. */\n"
"        if (!up) marks[nmark++] = w;\n"
"        if (w && out[w - 1] != '/') out[w++] = '/';\n"
"        memcpy(out + w, path + start, len);\n"
"        w += len;\n"
"    }\n"
"\n"
"    if (w == 0) out[w++] = '.';\n"
"    out[w] = '\\0';\n"
"    return out;\n"
"}\n"
"\n"
"static bool already_read(const Includer *in, const char *identity)\n"
"{\n"
"    for (int i = 0; i < in->ndone; i++)\n"
"        if (strcmp(in->done[i], identity) == 0) return true;\n"
"    return false;\n"
"}\n"
"\n"
"static void remember(Includer *in, char *identity)\n"
"{\n"
"    if (in->ndone == in->capdone) {\n"
"        int    cap = in->capdone ? in->capdone * 2 : 8;\n"
"        char **big = arena_alloc(in->a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, in->done, (size_t)in->ndone * sizeof *big);\n"
"        in->done    = big;\n"
"        in->capdone = cap;\n"
"    }\n"
"    in->done[in->ndone++] = identity;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* The joined text\n"
" *\n"
" * The same trick `%import` uses one level up: every file's text is held end to\n"
" * end in one buffer so that a position stays a single number, and a map says\n"
" * which file each stretch came from. Everything downstream keeps working with\n"
" * plain offsets and gets the right filename and line for free.\n"
" *\n"
" * The buffer is copied when it grows, and the copies are left behind in the\n"
" * arena rather than freed -- which is what makes it safe for a token read from\n"
" * an earlier revision to still point into it. Text is only ever appended, so\n"
" * an old copy holds the same bytes at the same offsets that the new one does.\n"
" */\n"
"static void unit_add(Includer *in, const char *path, size_t start, size_t size)\n"
"{\n"
"    SourceMap *m = in->map;\n"
"\n"
"    if (m->n == m->cap) {\n"
"        int   cap = m->cap ? m->cap * 2 : 8;\n"
"        Unit *big = arena_alloc(in->a, (size_t)cap * sizeof *big);\n"
"        memcpy(big, m->units, (size_t)m->n * sizeof *big);\n"
"        m->units = big;\n"
"        m->cap   = cap;\n"
"    }\n"
"    m->units[m->n++] = (Unit){ .path = path, .start = start, .size = size };\n"
"    in->src->map = m;\n"
"}\n"
"\n"
"static size_t join(Includer *in, const char *path, const Source *file)\n"
"{\n"
"    size_t start  = in->src->size;\n"
"    size_t need   = start + file->size + 1;\n"
"    char  *joined = arena_alloc(in->a, need + 1);\n"
"\n"
"    memcpy(joined, in->src->text, start);\n"
"    memcpy(joined + start, file->text, file->size);\n"
"    joined[need - 1] = '\\n';        /* so the last line of a file ends */\n"
"    joined[need]     = '\\0';\n"
"\n"
"    in->src->text = joined;\n"
"    in->src->size = need;\n"
"\n"
"    unit_add(in, path, start, file->size + 1);\n"
"    return start;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* The tree */\n"
"\n"
"static bool is_include(const Includer *in, const Value *v)\n"
"{\n"
"    return v && v->kind == V_NODE && v->type\n"
"        && strcmp(v->type, in->g->include_type) == 0;\n"
"}\n"
"\n"
"static Value *field_named(const Value *v, const char *field)\n"
"{\n"
"    if (v->kind != V_NODE || !v->fields) return NULL;\n"
"    for (int i = 0; i < v->n; i++)\n"
"        if (v->fields[i] && strcmp(v->fields[i], field) == 0) return v->items[i];\n"
"    return NULL;\n"
"}\n"
"\n"
"/* What an included file contributes to the list the include stood in. */\n"
"static bool splice_of(Includer *in, Value *root, const char *path, size_t blame,\n"
"                      Value ***items, int *n)\n"
"{\n"
"    if (root->kind == V_LIST) {\n"
"        *items = root->items;\n"
"        *n     = root->n;\n"
"        return true;\n"
"    }\n"
"    if (root->kind == V_NODE && root->n == 1 && root->items[0]\n"
"        && root->items[0]->kind == V_LIST) {\n"
"        *items = root->items[0]->items;\n"
"        *n     = root->items[0]->n;\n"
"        return true;\n"
"    }\n"
"\n"
"    diag_error(in->src, blame, \"'%s' has nothing to splice in\", path);\n"
"    if (root->kind == V_NODE && root->n == 1)\n"
"        diag_note(\"an included file's root has to be a list, or a node holding \"\n"
"                  \"one, and the one thing '%s' holds is %s\",\n"
"                  root->type, value_kind_name(root->items[0]));\n"
"    else if (root->kind == V_NODE)\n"
"        diag_note(\"an included file's root has to be a list, or a node holding \"\n"
"                  \"one, and '%s' holds %d\", root->type, root->n);\n"
"    else\n"
"        diag_note(\"an included file's root has to be a list, or a node holding \"\n"
"                  \"one, and this one is %s\", value_kind_name(root));\n"
"    return false;\n"
"}\n"
"\n"
"static void expand(Includer *in, Value *v, const char *from);\n"
"\n"
"/* Reads what one include names. Answers false having reported; answers true\n"
" * with `*n` of 0 for a file that has been read already, which is what ends a\n"
" * cycle and what makes two files free to include what each needs. */\n"
"static bool read_included(Includer *in, const Value *inc, const char *from,\n"
"                          Value ***items, int *n)\n"
"{\n"
"    *items = NULL;\n"
"    *n     = 0;\n"
"\n"
"    Value *named = field_named(inc, in->g->include_field);\n"
"    if (!named) {\n"
"        diag_error(in->src, inc->pos, \"this %s has no '%s' to name a file with\",\n"
"                   inc->type, in->g->include_field);\n"
"        return false;\n"
"    }\n"
"    if (named->kind != V_TEXT) {\n"
"        diag_error(in->src, inc->pos,\n"
"                   \"the file an include names has to be text, and this is %s\",\n"
"                   value_kind_name(named));\n"
"        return false;\n"
"    }\n"
"\n"
"    char *name = arena_strndup(in->a, named->text, named->len);\n"
"    if (!*name) {\n"
"        diag_error(in->src, inc->pos, \"this include names no file\");\n"
"        return false;\n"
"    }\n"
"\n"
"    /* Beside the file the include is *written in*, then the search path, in\n"
"     * the order the directories were given. An absolute name searches\n"
"     * nothing. */\n"
"    Source file;\n"
"    char  *path = NULL;\n"
"\n"
"    if (name[0] == '/') {\n"
"        path = name;\n"
"        if (!source_try(in->a, path, &file)) path = NULL;\n"
"    } else {\n"
"        path = path_beside(in->a, from, name);\n"
"        if (!source_try(in->a, path, &file)) {\n"
"            path = NULL;\n"
"            for (int i = 0; in->look && i < in->look->n; i++) {\n"
"                char *try = path_under(in->a, in->look->dirs[i], name);\n"
"                if (source_try(in->a, try, &file)) { path = try; break; }\n"
"            }\n"
"        }\n"
"    }\n"
"\n"
"    if (!path) {\n"
"        diag_error(in->src, inc->pos, \"cannot read the included file '%s'\", name);\n"
"        if (name[0] == '/') {\n"
"            diag_note(\"an absolute name is taken as it stands and searches \"\n"
"                      \"nothing\");\n"
"        } else {\n"
"            diag_note(\"looked beside %s, at %s\", from,\n"
"                      path_beside(in->a, from, name));\n"
"            for (int i = 0; in->look && i < in->look->n; i++)\n"
"                diag_note(\"and at %s\", path_under(in->a, in->look->dirs[i], name));\n"
"            if (!in->look || !in->look->n)\n"
"                diag_note(\"there is no search path -- `-I dir` adds one\");\n"
"        }\n"
"        return false;\n"
"    }\n"
"\n"
"    char *identity = identity_of(in->a, path);\n"
"    if (already_read(in, identity)) return true;   /* nothing, and no error */\n"
"    remember(in, identity);\n"
"\n"
"    if (in->depth >= INCLUDE_DEPTH) {\n"
"        diag_error(in->src, inc->pos, \"includes are nested more than %d deep\",\n"
"                   INCLUDE_DEPTH);\n"
"        return false;\n"
"    }\n"
"\n"
"    size_t start = join(in, path, &file);\n"
"\n"
"    /* Scanned over the file alone, so that a lexical error in it is reported\n"
"     * against its own line; the tokens are then moved into the joined text\n"
"     * once, here, and everything the matcher builds is positioned for good. */\n"
"    Source alone = { .path = path, .text = in->src->text + start,\n"
"                     .size = file.size, .map = NULL };\n"
"\n"
"    Tokens toks;\n"
"    if (!lex_run(in->a, in->g, &alone, &toks)) return false;\n"
"    for (int i = 0; i < toks.n; i++) toks.items[i].pos += start;\n"
"\n"
"    Value *root = parse_run(in->a, in->g, in->src, &toks);\n"
"    if (!root) return false;\n"
"\n"
"    in->depth++;\n"
"    expand(in, root, path);\n"
"    in->depth--;\n"
"    if (!in->ok) return false;\n"
"\n"
"    return splice_of(in, root, path, inc->pos, items, n);\n"
"}\n"
"\n"
"/* A list, rebuilt with every include in it opened out. */\n"
"static void expand_list(Includer *in, Value *list, const char *from)\n"
"{\n"
"    int cap = list->n;\n"
"    int n   = 0;\n"
"\n"
"    Value **out = arena_alloc(in->a, (size_t)(cap ? cap : 1) * sizeof *out);\n"
"\n"
"    for (int i = 0; i < list->n; i++) {\n"
"        Value *item = list->items[i];\n"
"\n"
"        if (is_include(in, item)) {\n"
"            Value **spliced;\n"
"            int     ns;\n"
"            if (!read_included(in, item, from, &spliced, &ns)) {\n"
"                in->ok = false;\n"
"                continue;\n"
"            }\n"
"            for (int k = 0; k < ns; k++) {\n"
"                if (n == cap) {\n"
"                    cap = cap ? cap * 2 : 8;\n"
"                    Value **big = arena_alloc(in->a, (size_t)cap * sizeof *big);\n"
"                    memcpy(big, out, (size_t)n * sizeof *big);\n"
"                    out = big;\n"
"                }\n"
"                out[n++] = spliced[k];\n"
"            }\n"
"            continue;\n"
"        }\n"
"\n"
"        expand(in, item, from);\n"
"        if (n == cap) {\n"
"            cap = cap ? cap * 2 : 8;\n"
"            Value **big = arena_alloc(in->a, (size_t)cap * sizeof *big);\n"
"            memcpy(big, out, (size_t)n * sizeof *big);\n"
"            out = big;\n"
"        }\n"
"        out[n++] = item;\n"
"    }\n"
"\n"
"    list->items = out;\n"
"    list->n     = n;\n"
"}\n"
"\n"
"static void expand(Includer *in, Value *v, const char *from)\n"
"{\n"
"    if (!v) return;\n"
"\n"
"    if (v->kind == V_LIST) { expand_list(in, v, from); return; }\n"
"    if (v->kind != V_NODE) return;\n"
"\n"
"    for (int i = 0; i < v->n; i++) {\n"
"        Value *kid = v->items[i];\n"
"        if (is_include(in, kid)) {\n"
"            /* The one place a splice has no meaning: a field wants one value\n"
"             * and a file is a number of them. Solveig refuses the same shape\n"
"             * for the same reason -- `x := @include \"f\"` is a compile error\n"
"             * there, and this is that error arriving from the other side. */\n"
"            diag_error(in->src, kid->pos,\n"
"                       \"an include stands here, where one value is wanted\");\n"
"            diag_note(\"a file can only be spliced into a list, and '%s' of \"\n"
"                      \"this %s is not one\",\n"
"                      v->fields && v->fields[i] ? v->fields[i] : \"a field\",\n"
"                      v->type ? v->type : \"node\");\n"
"            in->ok = false;\n"
"            continue;\n"
"        }\n"
"        expand(in, kid, from);\n"
"    }\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"bool include_expand(Arena *a, const Grammar *g, Source *src,\n"
"                    const IncludePath *look, Value *root)\n"
"{\n"
"    if (!g->include_type || !root) return true;\n"
"\n"
"    SourceMap *map = arena_alloc(a, sizeof *map);\n"
"    memset(map, 0, sizeof *map);\n"
"\n"
"    Includer in = { .a = a, .g = g, .src = src, .map = map, .look = look,\n"
"                    .ok = true };\n"
"\n"
"    /* The file the command line named is the first unit, and its text is the\n"
"     * buffer everything else is appended to -- so every position already\n"
"     * worked out for it stays what it was. */\n"
"    size_t size   = src->size;\n"
"    char  *joined = arena_alloc(a, size + 2);\n"
"    memcpy(joined, src->text, size);\n"
"    joined[size]     = '\\n';\n"
"    joined[size + 1] = '\\0';\n"
"\n"
"    src->text = joined;\n"
"    src->size = size + 1;\n"
"    unit_add(&in, src->path, 0, size + 1);\n"
"\n"
"    /* It counts as read, so a file that includes the one that included it, or\n"
"     * a library file of its own name, finds it already there and does nothing.\n"
"     */\n"
"    remember(&in, identity_of(a, src->path));\n"
"\n"
"    /* The one place `expand` cannot look, because it looks *into* things: a\n"
"     * file whose whole content is an include has no list around it and nothing\n"
"     * to be spliced into. Rare, and silent if it were left. */\n"
"    if (is_include(&in, root)) {\n"
"        diag_error(src, root->pos,\n"
"                   \"an include is the whole of this file, and there is nothing \"\n"
"                   \"here for it to be spliced into\");\n"
"        return false;\n"
"    }\n"
"\n"
"    expand(&in, root, src->path);\n"
"    return in.ok;\n"
"}\n"
"/* run.c -- running a pass over a tree.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * The model, stated plainly, because it is the thing that can be wrong\n"
" *\n"
" * **One walk, post-order, two phases at each node.**\n"
" *\n"
" *   1. entering  -- `down` clauses run, and what they define is visible to\n"
" *                   everything below this node and to nothing else\n"
" *   2. the children, left to right, each one walked whole\n"
" *   3. leaving   -- everything else runs: synthesised attributes, threaded\n"
" *                   updates, and the checks\n"
" *\n"
" * The sketch for this stage proposed demand-driven evaluation with\n"
" * memoisation, the way JastAdd does it. That was dropped, and the reason is\n"
" * worth keeping: **a threaded attribute needs a defined traversal order, and\n"
" * demand-driven evaluation has none.** Once a walk exists for `thread` to be\n"
" * threaded along, computing everything else during that same walk is simpler\n"
" * than being lazy, has no scheduling problem to solve, and cannot have a cycle\n"
" * because a node's attributes are computed strictly after its children's.\n"
" *\n"
" * What it costs: an attribute is computed whether or not anything reads it,\n"
" * and an attribute cannot refer *forward* to a node the walk has not reached.\n"
" * The first is nothing at these sizes. The second is what several passes and a\n"
" * `%driver` are for -- collect in one pass, use in the next, which is how a\n"
" * hand-written compiler handles forward references anyway.\n"
" *\n"
" * ---------------------------------------------------------------------------\n"
" * What `$name` means, in order\n"
" *\n"
" *   1. something the pattern bound\n"
" *   2. a field of the node being visited\n"
" *   3. an attribute of it, from an earlier pass or an earlier clause\n"
" *   4. a threaded attribute's value here\n"
" *   5. an inherited attribute in scope\n"
" *\n"
" * The order matters only when a name is used twice, and the innermost thing\n"
" * wins, which is what every language does.\n"
" */\n"
"\n"
"#include <string.h>\n"
"\n"
"/* What a pass has worked out about one node. */\n"
"typedef struct Attr Attr;\n"
"struct Attr {\n"
"    const char *name;\n"
"    Value      *value;\n"
"    Attr       *next;\n"
"};\n"
"\n"
"/* An inherited attribute, live for the subtree below the node that defined it. */\n"
"typedef struct Scope Scope;\n"
"struct Scope {\n"
"    const char *name;\n"
"    Value      *value;\n"
"    Scope      *outer;\n"
"};\n"
"\n"
"typedef struct {\n"
"    const char *name;\n"
"    Value      *value;\n"
"} Threaded;\n"
"\n"
"typedef struct {\n"
"    Arena         *a;\n"
"    const Grammar *g;\n"
"    const Source  *src;      /* the file being compiled, for messages */\n"
"    const Pass    *pass;\n"
"    const char    *stage;    /* its name, whichever kind of stage it is */\n"
"\n"
"    Threaded      *threads;\n"
"    Scope         *scope;\n"
"\n"
"    /* A rewrite sees bindings, `$pos` and fields, and nothing a pass worked\n"
"     * out: it runs to change the tree rather than to answer about it, and an\n"
"     * attribute read here would be reading a walk that has not happened. */\n"
"    bool           rewriting;\n"
"\n"
"    /* the node being visited, and what its pattern bound */\n"
"    Value         *node;\n"
"    const char   **bound;\n"
"    Value        **bounds;\n"
"    int            nbound;\n"
"} Run;\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Attributes on a node */\n"
"\n"
"static Value *attr_get(const Value *node, const char *name)\n"
"{\n"
"    for (Attr *at = node->attrs; at; at = at->next)\n"
"        if (strcmp(at->name, name) == 0) return at->value;\n"
"    return NULL;\n"
"}\n"
"\n"
"static void attr_set(Run *r, Value *node, const char *name, Value *value)\n"
"{\n"
"    for (Attr *at = node->attrs; at; at = at->next)\n"
"        if (strcmp(at->name, name) == 0) { at->value = value; return; }\n"
"\n"
"    Attr *at = arena_alloc(r->a, sizeof *at);\n"
"    at->name  = name;\n"
"    at->value = value;\n"
"    at->next  = node->attrs;\n"
"    node->attrs = at;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Matching a pattern */\n"
"\n"
"static bool match_pattern(Run *r, const Pattern *p, Value *v);\n"
"\n"
"static bool bind_name(Run *r, const char *name, Value *v)\n"
"{\n"
"    const char **names  = arena_alloc(r->a, (size_t)(r->nbound + 1) * sizeof *names);\n"
"    Value      **values = arena_alloc(r->a, (size_t)(r->nbound + 1) * sizeof *values);\n"
"\n"
"    memcpy(names,  r->bound,  (size_t)r->nbound * sizeof *names);\n"
"    memcpy(values, r->bounds, (size_t)r->nbound * sizeof *values);\n"
"\n"
"    names[r->nbound]  = name;\n"
"    values[r->nbound] = v;\n"
"\n"
"    r->bound  = names;\n"
"    r->bounds = values;\n"
"    r->nbound++;\n"
"    return true;\n"
"}\n"
"\n"
"static Value *field_of(const Value *node, const char *name)\n"
"{\n"
"    if (node->kind != V_NODE || !node->fields) return NULL;\n"
"    for (int i = 0; i < node->n; i++)\n"
"        if (node->fields[i] && strcmp(node->fields[i], name) == 0)\n"
"            return node->items[i];\n"
"    return NULL;\n"
"}\n"
"\n"
"static bool match_pattern(Run *r, const Pattern *p, Value *v)\n"
"{\n"
"    switch (p->kind) {\n"
"    case P_ANY:\n"
"        return true;\n"
"\n"
"    case P_BIND:\n"
"        return bind_name(r, p->name, v);\n"
"\n"
"    case P_TEXT:\n"
"        return v->kind == V_TEXT && v->len == (size_t)p->len\n"
"            && memcmp(v->text, p->name, v->len) == 0;\n"
"\n"
"    case P_INT:\n"
"        return v->kind == V_INT && v->ival == p->ival;\n"
"\n"
"    case P_BOOL:\n"
"        return v->kind == V_BOOL && (v->ival != 0) == (p->ival != 0);\n"
"\n"
"    case P_NIL:\n"
"        return v->kind == V_NIL;\n"
"\n"
"    case P_LIST:\n"
"        if (v->kind != V_LIST || v->n != p->nkids) return false;\n"
"        for (int i = 0; i < p->nkids; i++)\n"
"            if (!match_pattern(r, p->kids[i], v->items[i])) return false;\n"
"        return true;\n"
"\n"
"    case P_TYPE: {\n"
"        if (v->kind != V_NODE || !v->type || strcmp(v->type, p->name) != 0)\n"
"            return false;\n"
"\n"
"        /* A field the pattern does not mention is not looked at. */\n"
"        for (int i = 0; i < p->nkids; i++) {\n"
"            Value *got = field_of(v, p->fields[i]);\n"
"            if (!got) return false;\n"
"            if (!match_pattern(r, p->kids[i], got)) return false;\n"
"        }\n"
"        return true;\n"
"    }\n"
"    }\n"
"    return false;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Where a node came from\n"
" *\n"
" * `$pos` is the one name in a pass that is not a field, an attribute or a\n"
" * binding: every node has one and nothing in the notation could reach it.\n"
" * That is why a `.sob` written by `languages/solveig/` carried one line run\n"
" * for a whole chunk and no file table at all.\n"
" *\n"
" * **It answers a node rather than a number**, and that is the whole of the\n"
" * design. A byte offset would have been smaller and would have meant nothing\n"
" * to a description -- every use a description has for a position is a line or\n"
" * the name of a file. A node makes reading part of one an ordinary field read,\n"
" * so the notation needs no new syntax and no library function:\n"
" *\n"
" *     $pos.line     $pos.column     $pos.file\n"
" *\n"
" * and a fifth thing later is a field rather than a second reserved name.\n"
" * `$body.pos` over a list is a list of these, because `.` over a list already\n"
" * means that -- so a table with a row per statement is written the way every\n"
" * other list is.\n"
" *\n"
" * **A node is a stretch of source and not a point**, so it says where it ends\n"
" * as well as where it starts. That matters wherever something is emitted after\n"
" * the things it is about: a send's own bytes go in after its arguments, so the\n"
" * line they belong to is `$pos.endline` and not `$pos.line`. One file, because\n"
" * nothing yet ends in a different one from the one it began in and a node that\n"
" * did would be a construct spliced across an `@include`.\n"
" *\n"
" * The file is the one an `@include` put the node in, not the one the command\n"
" * line named, because that is what the joined source already knows.\n"
" */\n"
"static Value *position_of(Run *r, const Value *v)\n"
"{\n"
"    size_t end = v->endpos < v->pos ? v->pos : v->endpos;\n"
"\n"
"    int line, col, endline, endcol;\n"
"    source_position(r->src, v->pos, &line, &col);\n"
"    source_position(r->src, end,    &endline, &endcol);\n"
"\n"
"    const char *path = source_path_at(r->src, v->pos);\n"
"    if (!path) path = \"\";\n"
"\n"
"    Value *p = arena_alloc(r->a, sizeof *p);\n"
"    p->kind   = V_NODE;\n"
"    p->type   = \"Position\";\n"
"    p->pos    = v->pos;\n"
"    p->endpos = end;\n"
"    p->n      = 5;\n"
"    p->items  = arena_alloc(r->a, 5 * sizeof *p->items);\n"
"    p->fields = arena_alloc(r->a, 5 * sizeof *p->fields);\n"
"\n"
"    p->fields[0] = \"line\";      p->items[0] = value_int(r->a, line);\n"
"    p->fields[1] = \"column\";    p->items[1] = value_int(r->a, col);\n"
"    p->fields[2] = \"file\";      p->items[2] = value_text(r->a, path, strlen(path));\n"
"    p->fields[3] = \"endline\";   p->items[3] = value_int(r->a, endline);\n"
"    p->fields[4] = \"endcolumn\"; p->items[4] = value_int(r->a, endcol);\n"
"    return p;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* What a name means here */\n"
"\n"
"static Value *run_ref(Eval *e, const Expr *x)\n"
"{\n"
"    Run *r = e->data;\n"
"\n"
"    if (x->kind == X_ACC) {\n"
"        diag_error(&r->g->src, x->pos,\n"
"                   \"$$ belongs in a production's action, not in a pass\");\n"
"        return NULL;\n"
"    }\n"
"\n"
"    if (x->kind == X_DOT) {\n"
"        Value *of = eval_expr(e, x->kids[0]);\n"
"        if (!of) return NULL;\n"
"        if (value_failed(of)) return of;\n"
"\n"
"        /* An attribute of a **list** is that attribute of each element. It\n"
"         * is what `join($body.out)` has to mean, and writing it out by hand\n"
"         * would need a map, a lambda and a reason. */\n"
"        if (of->kind == V_LIST) {\n"
"            Value **items = arena_alloc(r->a, (size_t)(of->n ? of->n : 1)\n"
"                                               * sizeof *items);\n"
"            for (int i = 0; i < of->n; i++) {\n"
"                if (of->items[i]->kind != V_NODE) {\n"
"                    diag_error(&r->g->src, x->pos,\n"
"                               \"'.%s' over a list wants nodes, and element %d is %s\",\n"
"                               x->name, i + 1, value_kind_name(of->items[i]));\n"
"                    return NULL;\n"
"                }\n"
"                if (strcmp(x->name, \"pos\") == 0) {\n"
"                    items[i] = position_of(r, of->items[i]);\n"
"                    continue;\n"
"                }\n"
"                items[i] = field_of(of->items[i], x->name);\n"
"                if (!items[i] && !r->rewriting)\n"
"                    items[i] = attr_get(of->items[i], x->name);\n"
"                if (!items[i]) {\n"
"                    if (diag_failed()) return value_error(r->a);\n"
"                    diag_error(&r->g->src, x->pos,\n"
"                               \"'%s' has no field or attribute '%s' in %s '%s'\",\n"
"                               of->items[i]->type, x->name,\n"
"                               r->rewriting ? \"rewrite\" : \"pass\", r->stage);\n"
"                    return NULL;\n"
"                }\n"
"            }\n"
"            Value *list = arena_alloc(r->a, sizeof *list);\n"
"            list->kind  = V_LIST;\n"
"            list->items = items;\n"
"            list->n     = of->n;\n"
"            return list;\n"
"        }\n"
"\n"
"        if (of->kind != V_NODE) {\n"
"            diag_error(&r->g->src, x->pos,\n"
"                       \"'.%s' reads an attribute, and this is %s\",\n"
"                       x->name, value_kind_name(of));\n"
"            return NULL;\n"
"        }\n"
"        if (strcmp(x->name, \"pos\") == 0) return position_of(r, of);\n"
"\n"
"        /* A field of it, then what a pass worked out about it -- the same\n"
"         * order `$name` uses on the node being visited, so there is one rule\n"
"         * to know rather than two. */\n"
"        Value *got = field_of(of, x->name);\n"
"        if (!got && !r->rewriting) got = attr_get(of, x->name);\n"
"\n"
"        if (!got) {\n"
"            /* Once something has gone wrong, a missing attribute is very\n"
"             * likely a consequence of it rather than a mistake of its own. */\n"
"            if (diag_failed()) return value_error(r->a);\n"
"            diag_error(&r->g->src, x->pos,\n"
"                       \"'%s' has no field or attribute '%s' in %s '%s'\",\n"
"                       of->type, x->name,\n"
"                       r->rewriting ? \"rewrite\" : \"pass\", r->stage);\n"
"            return NULL;\n"
"        }\n"
"        return got;\n"
"    }\n"
"\n"
"    if (!x->name) {\n"
"        diag_error(&r->g->src, x->pos,\n"
"                   \"$%d numbers a production's factors, and a pass matches \"\n"
"                   \"nodes -- name the field instead\", x->index);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    /* 0. the position, before everything, so that `$pos` means one thing in\n"
"     * every clause of every pass. A description that had a field of that name\n"
"     * is refused when it is read, rather than getting a different answer here\n"
"     * from the one it gets three clauses down. */\n"
"    if (strcmp(x->name, \"pos\") == 0) return position_of(r, r->node);\n"
"\n"
"    for (int i = r->nbound - 1; i >= 0; i--)               /* 1. bound */\n"
"        if (strcmp(r->bound[i], x->name) == 0) return r->bounds[i];\n"
"\n"
"    Value *field = field_of(r->node, x->name);             /* 2. a field */\n"
"    if (field) return field;\n"
"\n"
"    if (r->rewriting) {\n"
"        diag_error(&r->g->src, x->pos,\n"
"                   \"nothing here is called '%s' -- a rewrite sees what its \"\n"
"                   \"pattern bound and the fields of the node it matched, and \"\n"
"                   \"nothing a pass worked out\", x->name);\n"
"        return NULL;\n"
"    }\n"
"\n"
"    /* 3. something a pass worked out about *this* node -- an earlier pass in\n"
"     * the driver, or an earlier clause of this one. Without this, reading\n"
"     * what a previous pass left required going through a child, which is a\n"
"     * strange thing to have to do to read your own attribute. */\n"
"    Value *own = attr_get(r->node, x->name);\n"
"    if (own) return own;\n"
"\n"
"    for (int i = 0; i < r->pass->nthreads; i++)            /* 4. threaded */\n"
"        if (strcmp(r->threads[i].name, x->name) == 0) {\n"
"            if (!r->threads[i].value) {\n"
"                diag_error(&r->g->src, x->pos,\n"
"                           \"'%s' is threaded but has no value yet -- \"\n"
"                           \"give it one on its `thread` line\", x->name);\n"
"                return NULL;\n"
"            }\n"
"            return r->threads[i].value;\n"
"        }\n"
"\n"
"    for (Scope *s = r->scope; s; s = s->outer)             /* 5. inherited */\n"
"        if (strcmp(s->name, x->name) == 0) return s->value;\n"
"\n"
"    diag_error(&r->g->src, x->pos,\n"
"               \"nothing here is called '%s' -- not a binding, a field of %s, \"\n"
"               \"an attribute of it, a threaded attribute, or one handed down\",\n"
"               x->name, r->node->type ? r->node->type : \"this node\");\n"
"    if (strcmp(x->name, \"line\") == 0 || strcmp(x->name, \"file\") == 0\n"
"        || strcmp(x->name, \"column\") == 0)\n"
"        diag_note(\"`$pos.%s` is where a node says that\", x->name);\n"
"    return NULL;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"static void walk(Run *r, Value *v);\n"
"\n"
"static const PassRule *find_rule(Run *r, Value *v)\n"
"{\n"
"    for (int i = 0; i < r->pass->nrules; i++) {\n"
"        r->nbound = 0;                       /* a failed match binds nothing */\n"
"        if (match_pattern(r, r->pass->rules[i].pattern, v))\n"
"            return &r->pass->rules[i];\n"
"    }\n"
"    r->nbound = 0;\n"
"    return NULL;\n"
"}\n"
"\n"
"/* A check is a **guard**, not a clause that happens to print.\n"
" *\n"
" * If one fires, this node's attributes are not computed -- they are set to a\n"
" * failure instead. `Binary(op: \"/\") ! $right.val = 0 : \"division by zero\"`\n"
" * would otherwise report the pass's own division by zero as well as its own\n"
" * message, and `Variable`'s undefined name would leave a nil for the addition\n"
" * above it to complain about separately. One mistake, one message.\n"
" *\n"
" * Which is why checks run first at a node, whatever order they were written in.\n"
" */\n"
"static bool checks_fired(Run *r, Value *v, const PassRule *rule, Eval *e)\n"
"{\n"
"    bool fired = false;\n"
"\n"
"    for (int i = 0; i < rule->nclauses; i++) {\n"
"        const Clause *c = &rule->clauses[i];\n"
"        if (c->kind != C_ERROR) continue;\n"
"\n"
"        e->pos = v->pos;\n"
"\n"
"        Value *cond = eval_expr(e, c->when);\n"
"        if (!cond)                { fired = true; continue; }\n"
"        if (value_failed(cond))   { fired = true; continue; }\n"
"\n"
"        if (cond->kind != V_BOOL) {\n"
"            diag_error(&r->g->src, c->pos,\n"
"                       \"a check wants a boolean, and this is %s\",\n"
"                       value_kind_name(cond));\n"
"            fired = true;\n"
"            continue;\n"
"        }\n"
"        if (!cond->ival) continue;\n"
"\n"
"        Value *message = eval_expr(e, c->value);\n"
"        if (!message || value_failed(message)) { fired = true; continue; }\n"
"\n"
"        if (message->kind != V_TEXT) {\n"
"            diag_error(&r->g->src, c->pos,\n"
"                       \"a check reports text, and this is %s\",\n"
"                       value_kind_name(message));\n"
"            fired = true;\n"
"            continue;\n"
"        }\n"
"        /* Reported against the file being compiled, at the node -- which is\n"
"         * the whole reason a node carries a position. */\n"
"        diag_error(r->src, v->pos, \"%.*s\", (int)message->len, message->text);\n"
"        fired = true;\n"
"    }\n"
"    return fired;\n"
"}\n"
"\n"
"/* Answers whether a check on this node fired, so that what runs after it can\n"
" * stop too -- the same reason the rule's own clauses do. */\n"
"static bool run_clauses(Run *r, Value *v, const PassRule *rule, bool entering)\n"
"{\n"
"    Eval e = { .a = r->a, .g = r->g, .ref = run_ref, .data = r };\n"
"\n"
"    bool blocked = false;\n"
"    if (!entering) blocked = checks_fired(r, v, rule, &e);\n"
"\n"
"    for (int i = 0; i < rule->nclauses; i++) {\n"
"        const Clause *c = &rule->clauses[i];\n"
"\n"
"        if ((c->kind == C_DOWN) != entering) continue;\n"
"\n"
"        if (c->kind == C_ERROR) continue;      /* done, above */\n"
"\n"
"        e.pos    = v->pos;\n"
"        e.endpos = v->endpos;\n"
"\n"
"        Value *got = blocked ? value_error(r->a) : eval_expr(&e, c->value);\n"
"\n"
"        /* A clause that could not be worked out leaves a failure in the\n"
"         * attribute rather than leaving it absent. Absent would make every\n"
"         * node above report that this one is missing something, which is the\n"
"         * same mistake said four more times. */\n"
"        if (!got) got = value_error(r->a);\n"
"\n"
"        switch (c->kind) {\n"
"        case C_SYNTH:\n"
"            attr_set(r, v, c->attr, got);\n"
"            break;\n"
"\n"
"        case C_THREAD:\n"
"            for (int k = 0; k < r->pass->nthreads; k++)\n"
"                if (strcmp(r->threads[k].name, c->attr) == 0)\n"
"                    r->threads[k].value = got;\n"
"            break;\n"
"\n"
"        case C_DOWN: {\n"
"            /* `down` on a **threaded** attribute sets the thread for the\n"
"             * subtree instead of binding a name over it, and that is what\n"
"             * makes a thread nest.\n"
"             *\n"
"             * A thread otherwise runs in one chain along the whole walk, which\n"
"             * is right for anything the program has one of and wrong for\n"
"             * anything a scope has its own of. A `.sob` method carries its own\n"
"             * name and constant tables, so entering one has to start them\n"
"             * empty and leaving one has to put the enclosing tables back --\n"
"             * a save and a restore, which is a stack, and a single chain has\n"
"             * no stack in it. With this, the save is an ordinary `down`\n"
"             * attribute and the restore is the node's own leaving clause,\n"
"             * both written in the notation rather than built in. */\n"
"            bool threaded = false;\n"
"            for (int k = 0; k < r->pass->nthreads; k++)\n"
"                if (strcmp(r->pass->threads[k], c->attr) == 0) { threaded = true; break; }\n"
"\n"
"            if (threaded) {\n"
"                for (int k = 0; k < r->pass->nthreads; k++)\n"
"                    if (strcmp(r->threads[k].name, c->attr) == 0)\n"
"                        r->threads[k].value = got;\n"
"                break;\n"
"            }\n"
"\n"
"            Scope *s = arena_alloc(r->a, sizeof *s);\n"
"            s->name  = c->attr;\n"
"            s->value = got;\n"
"            s->outer = r->scope;\n"
"            r->scope = s;\n"
"            break;\n"
"        }\n"
"        case C_ERROR:\n"
"            break;\n"
"        }\n"
"    }\n"
"    return blocked;\n"
"}\n"
"\n"
"/* Whether the rule a node matched has a clause for this attribute. That is\n"
" * what decides whether an `otherwise` runs -- a property of the rule and not\n"
" * of the node, so it is the same answer every time and can be read off the\n"
" * description. A node that matched no rule at all gets every one of them. */\n"
"static bool rule_defines(const PassRule *rule, const char *attr)\n"
"{\n"
"    if (!rule) return false;\n"
"\n"
"    for (int i = 0; i < rule->nclauses; i++)\n"
"        if (rule->clauses[i].attr && strcmp(rule->clauses[i].attr, attr) == 0)\n"
"            return true;\n"
"    return false;\n"
"}\n"
"\n"
"/* The defaults, after the node's own clauses so that they can read what those\n"
" * worked out. A field of the same name is the node answering too -- `.name`\n"
" * reads a field before an attribute -- which is the reading that makes\n"
" * `otherwise` mean \"unless the node says otherwise\" rather than \"unless a\n"
" * clause says otherwise\". */\n"
"static void run_defaults(Run *r, Value *v, const PassRule *rule, bool blocked)\n"
"{\n"
"    const Pass *p = r->pass;\n"
"    if (!p->ndefaults) return;\n"
"\n"
"    Eval e = { .a = r->a, .g = r->g, .ref = run_ref, .data = r,\n"
"               .pos = v->pos, .endpos = v->endpos };\n"
"\n"
"    for (int i = 0; i < p->ndefaults; i++) {\n"
"        const Clause *c = &p->defaults[i];\n"
"        if (rule_defines(rule, c->attr)) continue;\n"
"\n"
"        /* A node whose check fired gets a failure here too. Working the\n"
"         * default out would report consequences of the mistake already\n"
"         * reported, which is the thing `checks_fired` exists to stop. */\n"
"        Value *got = blocked ? value_error(r->a) : eval_expr(&e, c->value);\n"
"        if (!got) got = value_error(r->a);\n"
"\n"
"        if (c->kind == C_THREAD) {\n"
"            for (int k = 0; k < p->nthreads; k++)\n"
"                if (strcmp(r->threads[k].name, c->attr) == 0)\n"
"                    r->threads[k].value = got;\n"
"        } else {\n"
"            attr_set(r, v, c->attr, got);\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"static void walk(Run *r, Value *v)\n"
"{\n"
"    if (v->kind == V_LIST) {\n"
"        for (int i = 0; i < v->n; i++) walk(r, v->items[i]);\n"
"        return;\n"
"    }\n"
"    if (v->kind != V_NODE) return;\n"
"\n"
"    /* The state belonging to the node above is put back on the way out, so\n"
"     * that a sibling sees what its parent set and not what its sibling did. */\n"
"    Value       *outer_node   = r->node;\n"
"    const char **outer_bound  = r->bound;\n"
"    Value      **outer_bounds = r->bounds;\n"
"    int          outer_nbound = r->nbound;\n"
"    Scope       *outer_scope  = r->scope;\n"
"\n"
"    const PassRule *rule = find_rule(r, v);\n"
"    r->node = v;\n"
"\n"
"    if (rule) (void)run_clauses(r, v, rule, true);    /* entering: `down` */\n"
"\n"
"    /* The bindings belong to this node; its children rebind for themselves. */\n"
"    const char **mine   = r->bound;\n"
"    Value      **minev  = r->bounds;\n"
"    int          minen  = r->nbound;\n"
"\n"
"    for (int i = 0; i < v->n; i++) walk(r, v->items[i]);\n"
"\n"
"    r->node   = v;\n"
"    r->bound  = mine;\n"
"    r->bounds = minev;\n"
"    r->nbound = minen;\n"
"\n"
"    bool blocked = false;\n"
"    if (rule) blocked = run_clauses(r, v, rule, false);  /* leaving: the rest */\n"
"    run_defaults(r, v, rule, blocked);\n"
"\n"
"    r->node   = outer_node;\n"
"    r->bound  = outer_bound;\n"
"    r->bounds = outer_bounds;\n"
"    r->nbound = outer_nbound;\n"
"    r->scope  = outer_scope;\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"const Pass *pass_find(const Grammar *g, const char *name)\n"
"{\n"
"    for (int i = 0; i < g->npasses; i++)\n"
"        if (strcmp(g->passes[i].name, name) == 0) return &g->passes[i];\n"
"    return NULL;\n"
"}\n"
"\n"
"const Driver *driver_find(const Grammar *g, const char *name)\n"
"{\n"
"    for (int i = 0; i < g->ndrivers; i++)\n"
"        if (strcmp(g->drivers[i].name, name) == 0) return &g->drivers[i];\n"
"    return NULL;\n"
"}\n"
"\n"
"const Driver *driver_default(const Grammar *g)\n"
"{\n"
"    if (!g->ndrivers) return NULL;\n"
"\n"
"    /* An import is read before the file that imports it, so \"the first\n"
"     * declared\" would hand the default to the imported description -- and\n"
"     * `pascal-outline.phx` would run `pascal.phx`'s checker instead of its own\n"
"     * outline. The file named on the command line is the first unit. */\n"
"    if (g->map.n) {\n"
"        size_t from = g->map.units[0].start;\n"
"        size_t to   = from + g->map.units[0].size;\n"
"\n"
"        for (int i = 0; i < g->ndrivers; i++)\n"
"            if (g->drivers[i].pos >= from && g->drivers[i].pos < to)\n"
"                return &g->drivers[i];\n"
"    }\n"
"    return &g->drivers[0];\n"
"}\n"
"\n"
"bool pass_run(Arena *a, const Grammar *g, const Source *src,\n"
"              const Pass *pass, Value *root)\n"
"{\n"
"    Run r = { .a = a, .g = g, .src = src, .pass = pass, .stage = pass->name };\n"
"\n"
"    r.threads = arena_alloc(a, (size_t)(pass->nthreads ? pass->nthreads : 1)\n"
"                                * sizeof *r.threads);\n"
"\n"
"    Eval e = { .a = a, .g = g, .ref = run_ref, .data = &r };\n"
"    r.node = root;\n"
"\n"
"    for (int i = 0; i < pass->nthreads; i++) {\n"
"        r.threads[i].name  = pass->threads[i];\n"
"        r.threads[i].value = NULL;\n"
"\n"
"        if (pass->initial[i]) {\n"
"            r.threads[i].value = eval_expr(&e, pass->initial[i]);\n"
"            if (!r.threads[i].value) return false;\n"
"        }\n"
"    }\n"
"\n"
"    walk(&r, root);\n"
"    return !diag_failed();\n"
"}\n"
"\n"
"Value *pass_attr(const Value *node, const char *name)\n"
"{\n"
"    return attr_get(node, name);\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"/* Rewriting\n"
" *\n"
" * A pass answers *about* a node. Some things are answered by there being a\n"
" * different node, and that is what this is for -- the same patterns, the same\n"
" * evaluator, and a traversal that puts the answer back where the node was.\n"
" *\n"
" * The tree is edited in place, which is what lets a rewrite replace a node\n"
" * inside a list without the list's owner knowing. The root has no owner, so it\n"
" * comes back through `*root` instead.\n"
" */\n"
"\n"
"/* A node that reached itself, or a rule whose right-hand side matches its own\n"
" * left. `innermost` is the only strategy that can, and a cap is what turns a\n"
" * program that never finishes into a message with a position. */\n"
"#define REWRITE_ROUNDS 100\n"
"\n"
"/* Tries every rule, in order, and answers what the first match builds -- or\n"
" * the node itself when none matches. */\n"
"static Value *rewrite_once(Run *r, const Rewrite *rw, Value *v, bool *changed)\n"
"{\n"
"    *changed = false;\n"
"    if (!v) return v;\n"
"\n"
"    for (int i = 0; i < rw->nrules; i++) {\n"
"        r->nbound = 0;\n"
"        r->node   = v;\n"
"        if (!match_pattern(r, rw->rules[i].pattern, v)) continue;\n"
"\n"
"        /* Where the built node belongs is where the one it replaces was, so\n"
"         * that a diagnostic from a later pass points at the program rather\n"
"         * than at the rule that rewrote it. */\n"
"        Eval e = { .a = r->a, .g = r->g, .ref = run_ref, .data = r,\n"
"                   .pos = v->pos, .endpos = v->endpos };\n"
"\n"
"        Value *to = eval_expr(&e, rw->rules[i].to);\n"
"        if (!to) return NULL;\n"
"\n"
"        *changed = true;\n"
"        return to;\n"
"    }\n"
"    r->nbound = 0;\n"
"    return v;\n"
"}\n"
"\n"
"static Value *rewrite_value(Run *r, const Rewrite *rw, Value *v);\n"
"\n"
"/* Every child, in place. A node's fields and a list's elements are the same\n"
" * array, so this is one loop. */\n"
"static bool rewrite_kids(Run *r, const Rewrite *rw, Value *v)\n"
"{\n"
"    if (!v || (v->kind != V_NODE && v->kind != V_LIST)) return true;\n"
"\n"
"    for (int i = 0; i < v->n; i++) {\n"
"        Value *kid = rewrite_value(r, rw, v->items[i]);\n"
"        if (!kid) return false;\n"
"        v->items[i] = kid;\n"
"    }\n"
"    return true;\n"
"}\n"
"\n"
"static Value *rewrite_value(Run *r, const Rewrite *rw, Value *v)\n"
"{\n"
"    bool changed;\n"
"\n"
"    if (rw->how == R_TOPDOWN) {\n"
"        Value *now = rewrite_once(r, rw, v, &changed);\n"
"        if (!now) return NULL;\n"
"        if (!rewrite_kids(r, rw, now)) return NULL;\n"
"        return now;\n"
"    }\n"
"\n"
"    if (!rewrite_kids(r, rw, v)) return NULL;\n"
"\n"
"    Value *now = rewrite_once(r, rw, v, &changed);\n"
"    if (!now) return NULL;\n"
"    if (rw->how == R_BOTTOMUP || !changed) return now;\n"
"\n"
"    /* innermost: what a rule built is itself something a rule may be about,\n"
"     * and so are the children it built. */\n"
"    for (int round = 0; changed; round++) {\n"
"        if (round >= REWRITE_ROUNDS) {\n"
"            diag_error(r->src, now->pos,\n"
"                       \"'%s' has rewritten this %d times and is still going\",\n"
"                       rw->name, REWRITE_ROUNDS);\n"
"            diag_note(\"an innermost rewrite stops when nothing matches, so a \"\n"
"                      \"rule whose answer its own pattern matches never does\");\n"
"            return NULL;\n"
"        }\n"
"        if (!rewrite_kids(r, rw, now)) return NULL;\n"
"        now = rewrite_once(r, rw, now, &changed);\n"
"        if (!now) return NULL;\n"
"    }\n"
"    return now;\n"
"}\n"
"\n"
"const Rewrite *rewrite_find(const Grammar *g, const char *name)\n"
"{\n"
"    for (int i = 0; i < g->nrewrites; i++)\n"
"        if (strcmp(g->rewrites[i].name, name) == 0) return &g->rewrites[i];\n"
"    return NULL;\n"
"}\n"
"\n"
"bool rewrite_run(Arena *a, const Grammar *g, const Source *src,\n"
"                 const Rewrite *rw, Value **root)\n"
"{\n"
"    Run r = { .a = a, .g = g, .src = src, .stage = rw->name, .rewriting = true };\n"
"\n"
"    Value *now = rewrite_value(&r, rw, *root);\n"
"    if (!now) return false;\n"
"\n"
"    *root = now;\n"
"    return !diag_failed();\n"
"}\n"
"\n"
"/* ------------------------------------------------------------------ */\n"
"\n"
"bool driver_stage(Arena *a, const Grammar *g, const Source *src,\n"
"                  const char *name, Value **root)\n"
"{\n"
"    const Pass *pass = pass_find(g, name);\n"
"    if (pass) return pass_run(a, g, src, pass, *root);\n"
"\n"
"    const Rewrite *rw = rewrite_find(g, name);\n"
"    if (rw) return rewrite_run(a, g, src, rw, root);\n"
"\n"
"    diag_error(&g->src, 0, \"there is no pass or rewrite called '%s'\", name);\n"
"    return false;\n"
"}\n"
;
